#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_1 2
#define GPIO_LINE_2 3

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static volatile sig_atomic_t stop = 0;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    stop = 1;
}

int main()
{
    int ret;
    struct timespec sleep_time = {2, 0}; // 2 seconds

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line handles
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        perror("Error getting GPIO line 1");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return EXIT_FAILURE;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line1, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 1 for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop) {
        // Toggle GPIO 2
        ret = gpiod_line_set_value(line1, !gpiod_line_get_value(line1));
        if (ret < 0) {
            perror("Error setting GPIO line 1 value");
            break;
        }

        // Toggle GPIO 3
        ret = gpiod_line_set_value(line2, !gpiod_line_get_value(line2));
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }

        // Print current state
        printf("GPIO 2: %d, GPIO 3: %d\n", gpiod_line_get_value(line1), gpiod_line_get_value(line2));

        // Sleep for 2 seconds
        if (nanosleep(&sleep_time, NULL) < 0) {
            perror("nanosleep");
            break;
        }
    }

    // Clean up
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

