    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line handles for GPIO pins
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("Error getting line for GPIO 2");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Error getting line for GPIO 3");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return 1;
    }

    // Request lines for output
    ret = gpiod_line_request_output(line1, "example", 0);
    if (ret < 0) {
        perror("Error requesting line 1 for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "example", 0);
    if (ret < 0) {
        perror("Error requesting line 2 for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 2
        int value = gpiod_line_get_value(line1);
        gpiod_line_set_value(line1, !value);
        printf("GPIO %d: %d\n", GPIO_PIN_1, !value);

        // Toggle GPIO 3
