#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin to control
#define GPIO_PIN 2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int gpio_status;
    int i2c_handle;
    int sensor_value;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Open I2C device
        i2c_handle = i2cOpen(1, 0x48, 0); // Bus 1, address 0x48, no flags
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
            gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low on error
            sleep(5);
            continue; // Skip to the next iteration
        }

        // Read sensor value from I2C
        sensor_value = i2cReadByteData(i2c_handle, 0x00); // Register 0x00
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value: %d\n", sensor_value);
            i2cClose(i2c_handle);
            gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low on error
            sleep(5);
            continue; // Skip to the next iteration
        }

        // Validate sensor reading
        if (sensor_value < 0 || sensor_value > 1) {
            fprintf(stderr, "Invalid sensor reading: %d\n", sensor_value);
            i2cClose(i2c_handle);
            gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low on error
            sleep(5);
            continue; // Skip to the next iteration
        }

        // Set GPIO pin based on sensor value
        gpioWrite(GPIO_PIN, sensor_value);

        // Print sensor value and GPIO state
        printf("Sensor Value: %d, GPIO State: %d\n", sensor_value, gpioRead(GPIO_PIN));

        // Close I2C device
        i2cClose(i2c_handle);

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and exit
    gpioWrite(GPIO_PIN, 0); // Set GPIO to LOW before exiting
    gpioTerminate(); // Terminate pigpio
    return 0;
}

