#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout in microseconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to trigger the HC-SR04
void trigger_hc_sr04() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance in centimeters
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    trigger_hc_sr04();

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate the pulse duration
    diff_tick = end_tick - start_tick;

    // Calculate the distance
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        sleep(60); // Wait 60 seconds
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_ACTV_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON_LATCH 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the I2C device
int write_i2c_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure ADS1115 for single conversion
        uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;
        if (write_i2c_word(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Error configuring ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion result
        uint16_t reading;
        if (read_i2c_word(i2c_fd, ADS1115_REG_CONVERT, &reading) < 0) {
            fprintf(stderr, "Error reading ADS1115 conversion result\n");
            close(i2c_fd);
            return 1;
        }

        // Print the reading
        printf("ADS1115 Reading: %d\n", reading);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_set_value(line, 0); // Set GPIO to LOW
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    int ret;
    struct timespec sleep_time;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line description
    const char *line_name = gpiod_chip_get_line_name(chip, GPIO_PIN);
    if (!line_name) {
        fprintf(stderr, "Error: GPIO %d is not available on chip %s\n", GPIO_PIN, GPIO_CHIP);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line, "gpio-output", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set sleep time for 1 second
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;

    // Main loop
    while (1) {
        // Toggle the GPIO state
        int current_value = gpiod_line_get_value(line);
        int new_value = !current_value;
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }

        // Report the new state
        printf("GPIO %d is now %s\n", GPIO_PIN, new_value ? "HIGH" : "LOW");

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (in case of error)
    gpiod_line_set_value(line, 0); // Set GPIO to LOW
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define GPIO_LINE 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t stop = 0;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    stop = 1;
}

int main()
{
    int i;
    int ret;
    struct timespec ts;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (i = 0; i < 3 && !stop; i++) {
        // Set GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Print timestamp and GPIO state
        printf("[%ld.%09ld] GPIO %d set to HIGH\n", ts.tv_sec, ts.tv_nsec, GPIO_PIN);

        // Wait for 2 seconds
        sleep(2);

        // Set GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Print timestamp and GPIO state
        printf("[%ld.%09ld] GPIO %d set to LOW\n", ts.tv_sec, ts.tv_nsec, GPIO_PIN);

        // Wait for 2 seconds
        sleep(2);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");

    return 0;
}

