        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }

    return 0;
}

// Function to read the ADC value from AIN0
int read_adc(int fd, int16_t *value) {
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;

    if (write_i2c_word(fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to start conversion\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    if (read_i2c_word(fd, ADS1115_REG_CONVERT, (uint16_t*)value) != 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    return 0;
}

