        return 1;
    }

    // Check if the value is valid
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid value. Exiting.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line value
    rc = gpiod_line_set_value(line, value);
    if (rc < 0) {
        perror("Error setting GPIO value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print the applied value
    printf("Applied value: %d\n", value);

    // Clean up and exit
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

