{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an output
    gpioSetMode(GPIO_4, PI_OUTPUT);

    // Set GPIO 18 as an output
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Toggle the state of GPIO 4
        int current_state_4 = gpioRead(GPIO_4);
        gpioWrite(GPIO_4, !current_state_4);
        printf("GPIO %d: %d\n", GPIO_4, !current_state_4);

        // Toggle the state of GPIO 18
        int current_state_18 = gpioRead(GPIO_18);
        gpioWrite(GPIO_18, !current_state_18);
        printf("GPIO %d: %d\n", GPIO_18, !current_state_18);

        // Wait for 0.05 seconds
        gpioDelay(50000); // 50000 microseconds = 0.05 seconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

