#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40

// Define the command to read temperature
#define SI7021_TEMP_CMD 0xE3

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature from the SI7021 sensor
float read_temperature() {
    unsigned char buf[2];
    int result;

    // Send the temperature measurement command
    buf[0] = SI7021_TEMP_CMD;
    result = write(i2c_fd, buf, 1);
    if (result != 1) {
        perror("Failed to write temperature command");
        return -1.0;
    }

    // Wait for the measurement to complete (datasheet recommends at least 20ms)
    usleep(20000); // 20ms

    // Read the temperature data (2 bytes)
    result = read(i2c_fd, buf, 2);
    if (result != 2) {
        perror("Failed to read temperature data");
        return -1.0;
    }

    // Convert the raw data to temperature in Celsius
    unsigned int raw_temperature = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    return temperature;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print temperature every 5 seconds
    while (1) {
        float temperature = read_temperature();

        if (temperature < -40.0 || temperature > 125.0) {
            fprintf(stderr, "Error: Temperature reading out of range: %.2f\n", temperature);
        } else {
            printf("Temperature: %.2f °C\n", temperature);
        }

        sleep(5);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000   // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define CONFIG_DR_128SPS 0x0060    // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_ACTV_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON_LATCH 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Function to write a 16-bit value to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from an I2C register
int read_i2c_reg(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    int i2c_fd;
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int retries = 3; // Number of retries for I2C initialization

    while (retries > 0) {
        i2c_fd = open(i2c_device, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C device");
            retries--;
            sleep(1); // Wait before retrying
        } else {
            break; // I2C device opened successfully
        }
    }

    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device after multiple retries. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure the ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;

    if (write_i2c_reg(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to write configuration register. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    uint16_t conversion;
    if (read_i2c_reg(i2c_fd, ADS1115_REG_CONVERT, &conversion) < 0) {
        fprintf(stderr, "Failed to read conversion register. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Print the reading
    printf("ADC Value: %d\n", conversion);

    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_8 8
#define GPIO_LINE_9 9
#define GPIO_LINE_10 10
#define GPIO_LINE_11 11
#define GPIO_LINE_23 23
#define GPIO_LINE_24 24

// Define the number of cycles
#define NUM_CYCLES 256

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line8, *line9, *line10, *line11, *line23, *line24;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line8) {
        gpiod_line_release(line8);
    }
    if (line9) {
        gpiod_line_release(line9);
    }
    if (line10) {
        gpiod_line_release(line10);
    }
    if (line11) {
        gpiod_line_release(line11);
    }
    if (line23) {
        gpiod_line_release(line23);
    }
    if (line24) {
        gpiod_line_release(line24);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int i;
    int ret;
    struct timespec delay = {0, 100000000L}; // 100ms

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line8 = gpiod_chip_get_line(chip, GPIO_LINE_8);
    line9 = gpiod_chip_get_line(chip, GPIO_LINE_9);
    line10 = gpiod_chip_get_line(chip, GPIO_LINE_10);
    line11 = gpiod_chip_get_line(chip, GPIO_LINE_11);
    line23 = gpiod_chip_get_line(chip, GPIO_LINE_23);
    line24 = gpiod_chip_get_line(chip, GPIO_LINE_24);

    if (!line8 || !line9 || !line10 || !line11 || !line23 || !line24) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line8, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 8 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line9, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 9 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line10, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 10 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line11, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 11 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line23, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 23 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line24, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 24 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO states
        gpiod_line_set_value(line8, (i % 2) ? 1 : 0);
        gpiod_line_set_value(line9, (i % 3) ? 1 : 0);
        gpiod_line_set_value(line10, (i % 5) ? 1 : 0);
        gpiod_line_set_value(line11, (i % 7) ? 1 : 0);
        gpiod_line_set_value(line23, (i % 11) ? 1 : 0);
        gpiod_line_set_value(line24, (i % 13) ? 1 : 0);

        // Print GPIO states
        printf("Cycle %d: 8=%d, 9=%d, 10=%d, 11=%d, 23=%d, 24=%d\n",
               i,
               gpiod_line_get_value(line8),
               gpiod_line_get_value(line9),
               gpiod_line_get_value(line10),
               gpiod_line_get_value(line11),
               gpiod_line_get_value(line23),
               gpiod_line_get_value(line24));

        // Delay
        nanosleep(&delay, NULL);
    }

    // Cleanup (should not reach here normally due to signal handler)
    gpiod_line_release(line8);
    gpiod_line_release(line9);
    gpiod_line_release(line10);
    gpiod_line_release(line11);
    gpiod_line_release(line23);
    gpiod_line_release(line24);
    gpiod_chip_close(chip);

    return 0;
}

