#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 2

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int gpio_status;
    int user_input;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Enter 0 or 1 to control GPIO %d, or -1 to exit.\n", GPIO_PIN);

    while (!terminate) {
        printf("Enter value: ");
        if (scanf("%d", &user_input) != 1) {
            fprintf(stderr, "Invalid input. Please enter 0, 1, or -1.\n");
            // Clear the input buffer
            while (getchar() != '\n');
            continue;
        }

        if (user_input == -1) {
            break;
        }

        if (user_input == 0 || user_input == 1) {
            gpio_status = gpioWrite(GPIO_PIN, user_input);
            if (gpio_status == 0) {
                printf("GPIO %d set to %d\n", GPIO_PIN, user_input);
            } else {
                fprintf(stderr, "Failed to write to GPIO %d\n", GPIO_PIN);
            }
        } else {
            fprintf(stderr, "Invalid input. Please enter 0, 1, or -1.\n");
        }

        sleep(1);
    }

    // Clean up and exit
    gpioWrite(GPIO_PIN, 0); // Set GPIO to LOW before exiting
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

