    }
    exit(0);
}

int main()
{
    int ret;
    struct timespec sleep_time;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line description
    const char *line_name = gpiod_chip_get_line_name(chip, GPIO_PIN);
    if (!line_name) {
        fprintf(stderr, "Error: GPIO %d is not available on chip %s\n", GPIO_PIN, GPIO_CHIP);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line, "gpio-output", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set sleep duration for 1 second
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;

    // Main loop
    while (1) {
        // Toggle the GPIO state
        int current_value = gpiod_line_get_value(line);
        int new_value = !current_value;
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }

        // Report the new state
        printf("GPIO %d is now %s\n", GPIO_PIN, new_value ? "HIGH" : "LOW");

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (in case of error)
    gpiod_line_set_value(line, 0); // Set GPIO to LOW
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Toggle the state of GPIO 17
        int current_state = gpioRead(GPIO_17);
        gpioWrite(GPIO_17, !current_state);

        // Toggle the state of GPIO 18
        current_state = gpioRead(GPIO_18);
        gpioWrite(GPIO_18, !current_state);

        // Toggle the state of GPIO 27
        current_state = gpioRead(GPIO_27);
        gpioWrite(GPIO_27, !current_state);

        // Report the current states to standard output
        printf("GPIO 17: %d, GPIO 18: %d, GPIO 27: %d\n",
               gpioRead(GPIO_17), gpioRead(GPIO_18), gpioRead(GPIO_27));

        // Wait for 0.05 seconds
        gpioDelay(50000); // 50000 microseconds = 0.05 seconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

