#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define constants
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x48
#define I2C_REG 0x00
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_i2c_register(int fd, unsigned char reg);
int write_gpio(struct gpiod_line *line, int value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_i2c_register(int fd, unsigned char reg) {
    int retries = I2C_RETRY_COUNT;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
            fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error: Could not write register address: %s\n", strerror(errno));
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Sleep for 10ms
            continue;
        }

        unsigned char data;
        if (read(fd, &data, 1) == 1) {
            return data;
        } else {
            fprintf(stderr, "Error: Could not read data: %s\n", strerror(errno));
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Sleep for 10ms
        }
    }

    fprintf(stderr, "Error: Failed to read I2C register after multiple retries.\n");
    return -1;
}

// Function to write a value to a GPIO line
int write_gpio(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error: Could not get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio-control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(gpio_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        int sensor_value = read_i2c_register(i2c_fd, I2C_REG);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: Could not read sensor data.\n");
        } else {
            // Control GPIO based on sensor value
            if (sensor_value == 0) {
                if (write_gpio(gpio_line, 1) != 0) {
                    fprintf(stderr, "Error: Could not set GPIO high.\n");
                }
            } else {
                if (write_gpio(gpio_line, 0) != 0) {
                    fprintf(stderr, "Error: Could not set GPIO low.\n");
                }
            }

            // Print sensor value and GPIO state
            printf("Sensor Value: %d, GPIO State: %d\n", sensor_value, gpiod_line_get_value(gpio_line));
        }

        // Wait 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

