#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i;
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO %d control started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate) {
        // Toggle the GPIO pin state
        result = gpioWrite(GPIO_PIN, !gpioRead(GPIO_PIN));
        if (result != 0) {
            fprintf(stderr, "Error writing to GPIO %d: %d\n", GPIO_PIN, result);
            break; // Exit loop on error
        }

        // Print the current state
        printf("GPIO %d: %s\n", GPIO_PIN, gpioRead(GPIO_PIN) ? "HIGH" : "LOW");

        // Wait for 1 millisecond
        usleep(1000); // 1000 microseconds = 1 millisecond
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("GPIO %d control stopped.\n", GPIO_PIN);

    return 0;
}

