    struct timespec sleep_time;

    // Initialize sleep time
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
