        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_PIN_1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_2, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Generate random values for GPIO pin states
        gpio_pin_1_state = rand() % 2; // 0 or 1
        gpio_pin_2_state = rand() % 2; // 0 or 1

        // Write the states to the GPIO pins
        gpioWrite(GPIO_PIN_1, gpio_pin_1_state);
        gpioWrite(GPIO_PIN_2, gpio_pin_2_state);

        // Report the states to standard output
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, gpio_pin_1_state, GPIO_PIN_2, gpio_pin_2_state);

        // Wait for 5 seconds
