// Define GPIO pins
#define GPIO_PIN_1 17
#define GPIO_PIN_2 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2;

// Function prototypes
int read_gpio_value(struct gpiod_line *line);
int write_gpio_value(struct gpiod_line *line, int value);
void cleanup(int signal);

// Signal handler for graceful exit
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the value of a GPIO line
int read_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to write a value to a GPIO line
int write_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error writing GPIO value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1; // Exit with error
    }

    // Get GPIO line handles
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        return 1; // Exit with error
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return 1; // Exit with error
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN_1, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1; // Exit with error
    }

    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN_2, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return 1; // Exit with error
    }

    // Read initial values
    int value1 = read_gpio_value(line1);
    int value2 = read_gpio_value(line2);

    if (value1 < 0 || value2 < 0) {
        fprintf(stderr, "Error reading initial GPIO values. Exiting.\n");
        cleanup(0);
        return 1;
    }

    // Print initial values
    printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, value1, GPIO_PIN_2, value2);

    // Toggle the values
    if (write_gpio_value(line1, !value1) < 0) {
        fprintf(stderr, "Error writing to GPIO %d. Exiting.\n", GPIO_PIN_1);
        cleanup(0);
        return 1;
    }
    if (write_gpio_value(line2, !value2) < 0) {
        fprintf(stderr, "Error writing to GPIO %d. Exiting.\n", GPIO_PIN_2);
        cleanup(0);
        return 1;
    }

    // Read toggled values
    value1 = read_gpio_value(line1);
    value2 = read_gpio_value(line2);

    if (value1 < 0 || value2 < 0) {
        fprintf(stderr, "Error reading toggled GPIO values. Exiting.\n");
        cleanup(0);
        return 1;
    }

    // Print toggled values
    printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, value1, GPIO_PIN_2, value2);

    // Cleanup and exit
    cleanup(0);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define DHT11_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht11(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioSetMode(gpio, PI_INPUT);

    /* Wait for the DHT11 to pull the line low (response signal) */
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout if DHT11 doesn't respond
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout if DHT11 doesn't respond
    }

    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout if DHT11 doesn't respond
    }

    /* Read the 40 bits of data */
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            timeout = 0;
            while (gpioRead(gpio) == 0) {
                gpioDelay(1);
                timeout++;
                if (timeout > 100) return -1; // Timeout
            }

            gpioDelay(30); // Wait for the bit to go high

            if (gpioRead(gpio) == 1) {
                data[i] |= (1 << (7 - j));
            }

            timeout = 0;
            while (gpioRead(gpio) == 1) {
                gpioDelay(1);
                timeout++;
                if (timeout > 100) return -1; // Timeout
            }
        }
    }

    /* Validate checksum */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -2; // Checksum error
    }

    *humidity = (float)data[0];
    *temperature = (float)data[2];

    return 0; // Success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    result = read_dht11(DHT11_GPIO, &temperature, &humidity);

    if (result == 0) {
        printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", temperature, humidity);
    } else {
        fprintf(stderr, "DHT11 read failed with error code: %d\n", result);
        if (result == -1) {
            fprintf(stderr, "Error: DHT11 not responding.\n");
        } else if (result == -2) {
            fprintf(stderr, "Error: DHT11 checksum error.\n");
        }
    }

    gpioTerminate();
    return result == 0 ? 0 : 1;
}

