#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define GPIO_LINE 18

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t stop = 0;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    stop = 1;
}

int main()
{
    int i;
    int ret;
    struct timespec ts;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (i = 0; i < 3 && !stop; i++) {
        // Set GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Print timestamp and GPIO state
        printf("[%ld.%09ld] GPIO %d set to HIGH\n", ts.tv_sec, ts.tv_nsec, GPIO_PIN);

        // Wait for 0.1 seconds
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL);

        // Set GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Print timestamp and GPIO state
        printf("[%ld.%09ld] GPIO %d set to LOW\n", ts.tv_sec, ts.tv_nsec, GPIO_PIN);

        // Wait for 0.1 seconds
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");

    return 0;
}

