#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1" // Standard I2C bus on Raspberry Pi
#define OPT3001_ADDR 0x44

// Function to read a register from the OPT3001
int read_register(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Function to write a register to the OPT3001
int write_register(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to register");
        return -1;
    }
    return 0;
}

// Function to read the result register and convert it to lux
float read_lux(int fd)
{
    int result = read_register(fd, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error reading result register\n");
        return -1.0;
    }

    uint16_t raw_result = (uint16_t)result;
    uint16_t exponent = (raw_result >> 12) & 0x0F;
    uint16_t mantissa = raw_result & 0x0FFF;

    float lux = mantissa * (0.01 * (1 << exponent));
    return lux;
}

int main()
{
    int fd;

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set OPT3001 address
    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Configure OPT3001 for continuous conversion mode (100ms)
    if (write_register(fd, 0x01, 0xCC10) < 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        close(fd);
        return 1;
    }

    // Read and print lux values continuously
    while (1) {
        float lux = read_lux(fd);
        if (lux >= 0) {
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }
        sleep(1);
    }

    // Close I2C bus (this part will not be reached in the infinite loop)
    close(fd);

    return 0;
}

