// Function prototypes
int read_i2c_data(int fd, int address, int reg);
int validate_i2c_data(int data);
int set_gpio_output(struct gpiod_line *line, int value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }

    // Close I2C file descriptor
    if (i2c_fd > 0) {
        close(i2c_fd);
    }

    // Release GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// Function to read data from I2C device
int read_i2c_data(int fd, int address, int reg) {
    int data;

    // Write the register address to the I2C device
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    // Write the register address to the I2C device
    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write to I2C device");
        return -1;
    }

    // Read data from the I2C device
    if (read(fd, &data, 1) != 1) {
        perror("Error: Could not read from I2C device");
        return -1;
    }

    return data;
}

// Function to validate I2C data
int validate_i2c_data(int data) {
    // Define valid range for I2C data (0-255)
    if (data >= 0 && data <= 255) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error: Could not set GPIO value");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_data;
    int gpio_value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error: Could not open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line 1
    gpio_line_1 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_1);
    if (!gpio_line_1) {
        perror("Error: Could not get GPIO line 1");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line 2
    gpio_line_2 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_2);
    if (!gpio_line_2) {
        perror("Error: Could not get GPIO line 2");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line_1);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line 1 for output
    if (gpiod_line_request_output(gpio_line_1, "gpio-control", 0) < 0) {
        perror("Error: Could not request GPIO line 1 for output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line 2 for output
    if (gpiod_line_request_output(gpio_line_2, "gpio-control", 0) < 0) {
        perror("Error: Could not request GPIO line 2 for output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from I2C device
        i2c_data = read_i2c_data(i2c_fd, I2C_ADDRESS, I2C_REGISTER);

        // Validate I2C data
        if (validate_i2c_data(i2c_data)) {
            // Set GPIO output based on I2C data
            gpio_value = (i2c_data & 0x01) ? 1 : 0; // Example: Bit 0 determines GPIO 2
            if (set_gpio_output(gpio_line_2, gpio_value) < 0) {
                fprintf(stderr, "Error setting GPIO 2\n");
            }

            gpio_value = (i2c_data & 0x02) ? 1 : 0; // Example: Bit 1 determines GPIO 3
            if (set_gpio_output(gpio_line_1, gpio_value) < 0) {
                fprintf(stderr, "Error setting GPIO 1\n");
            }

            // Print GPIO values
            printf("GPIO 2: %d, GPIO 3: %d\n", gpio_value, (i2c_data & 0x02) ? 1 : 0);
        } else {
            fprintf(stderr, "Invalid I2C data: %d\n", i2c_data);
        }

        // Delay for 1 second
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
