#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_17, PI_OUTPUT);

    // Set GPIO 18 as an output
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Main loop to control the GPIO pins
    while (!terminate)
    {
        // Toggle the state of GPIO 17
        gpioWrite(GPIO_17, !gpioRead(GPIO_17));

        // Toggle the state of GPIO 18
        gpioWrite(GPIO_18, !gpioRead(GPIO_18));

        // Report the current state of GPIO 17 and GPIO 18
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_17, gpioRead(GPIO_17), GPIO_18, gpioRead(GPIO_18));

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500000 microseconds = 0.5 seconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0; // Exit successfully
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

// Define the UART port (e.g., /dev/ttyS0 or /dev/ttyAMA0)
#define UART_PORT "/dev/ttyS0"

// Define the baud rate (e.g., 9600)
#define BAUD_RATE B9600

// Define the timeout in seconds (e.g., 1)
#define TIMEOUT 1

// Global variable for the UART file descriptor
int uart_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (uart_fd != -1) {
        close(uart_fd);
    }
    exit(0);
}

// Function to initialize the UART port
int init_uart(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = TIMEOUT; // Wait for up to 1 second (TIMEOUT * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    }
}

// Function to print the received data with a timestamp
void print_data(const char *data) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("[%s] %s\n", buf, data);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the UART port
    uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to initialize UART. Exiting.\n");
        return 1;
    }

    char buffer[256];

    // Main loop to read and print data
    while (1) {
        int bytes_read = read_uart(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            print_data(buffer);
        } else if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            sleep(1); // Wait before retrying
        } else {
            // No data received, sleep briefly to avoid busy-waiting
            usleep(100000); // 100ms
        }
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup for completeness.
    close(uart_fd);
    return 0;
}

