#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO pin number (BCM numbering)
#define GPIO_PIN 2

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the base path for the GPIO chip
#define GPIO_PATH "/sys/class/gpio"

// Define the log file path
#define LOG_FILE "gpio_control.log"

// Global variables for GPIO line and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Function prototypes
int read_gpio_value(int gpio_pin);
int write_gpio_value(int gpio_pin, int value);
int log_message(const char *message);
void signal_handler(int sig);
int export_gpio(int gpio_pin);
int unexport_gpio(int gpio_pin);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        log_message("Caught SIGINT, exiting gracefully.");

        // Unexport the GPIO pin
        if (line) {
            gpiod_line_release(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }

        // Unexport the GPIO pin
        unexport_gpio(GPIO_PIN);

        exit(0);
    }
}

// Function to export the GPIO pin
int export_gpio(int gpio_pin) {
    char export_path[64];
    FILE *fp;

    snprintf(export_path, sizeof(export_path), "%s/export", GPIO_PATH);

    fp = fopen(export_path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO export file");
        return -1;
    }

    fprintf(fp, "%d", gpio_pin);
    fclose(fp);

    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int gpio_pin) {
    char unexport_path[64];
    FILE *fp;

    snprintf(unexport_path, sizeof(unexport_path), "%s/unexport", GPIO_PATH);

    fp = fopen(unexport_path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO unexport file");
        return -1;
    }

    fprintf(fp, "%d", gpio_pin);
    fclose(fp);

    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int gpio_pin) {
    char value_path[64];
    FILE *fp;
    int value;

    snprintf(value_path, sizeof(value_path), "%s/gpio%d/value", GPIO_PATH, gpio_pin);

    fp = fopen(value_path, "r");
    if (fp == NULL) {
        perror("Failed to open GPIO value file for reading");
        return -1;
    }

    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Failed to read GPIO value\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    return value;
}

// Function to write the GPIO value
int write_gpio_value(int gpio_pin, int value) {
    char value_path[64];
    FILE *fp;

    snprintf(value_path, sizeof(value_path), "%s/gpio%d/value", GPIO_PATH, gpio_pin);

    fp = fopen(value_path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO value file for writing");
        return -1;
    }

    fprintf(fp, "%d", value);
    fclose(fp);

    return 0;
}

// Function to log messages to a file
int log_message(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);

    return 0;
}

int main() {
    int i;
    int current_value;
    int new_value;
    char log_buffer[256];

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        log_message("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        log_message("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "gpio_control", 0) < 0) {
        perror("Failed to request GPIO line for output");
        log_message("Failed to request GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (i = 0; i < 3; i++) {
        // Read the current GPIO value
        current_value = read_gpio_value(GPIO_PIN);
        if (current_value < 0) {
            fprintf(stderr, "Failed to read GPIO value, exiting.\n");
            log_message("Failed to read GPIO value, exiting.");
            break;
        }

        // Toggle the GPIO value
        new_value = (current_value == 0) ? 1 : 0;

        // Write the new GPIO value
        if (write_gpio_value(GPIO_PIN, new_value) < 0) {
            fprintf(stderr, "Failed to write GPIO value, exiting.\n");
            log_message("Failed to write GPIO value, exiting.");
            break;
        }

        // Log the new GPIO value
        snprintf(log_buffer, sizeof(log_buffer), "GPIO %d set to %d", GPIO_PIN, new_value);
        log_message(log_buffer);

        // Wait for 60 seconds
        sleep(60);
    }

    // Unexport the GPIO pin
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Unexport the GPIO pin
    unexport_gpio(GPIO_PIN);

    return 0;
}

