#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_LINE 2

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t stop = 0;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    stop = 1;
}

int main()
{
    int i;
    int ret;
    struct timespec ts;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (i = 0; i < 3 && !stop; i++) {
        // Set GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        // Print current state
        printf("GPIO %d is HIGH\n", GPIO_PIN);

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Wait for 0.1 seconds
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL);

        // Set GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        // Print current state
        printf("GPIO %d is LOW\n", GPIO_PIN);

        // Get current timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Wait for 0.1 seconds
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");

    return 0;
}

