#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define MAX_SENSORS 10
#define MAX_SENSOR_ID_LENGTH 20
#define MAX_LINE_LENGTH 256

// Structure to hold sensor information
typedef struct {
    char id[MAX_SENSOR_ID_LENGTH];
    char path[MAX_LINE_LENGTH];
    int valid;
} sensor_t;

// Global array to store sensor information
sensor_t sensors[MAX_SENSORS];
int num_sensors = 0;

// Function prototypes
int discover_sensors();
int read_temperature(const char *sensor_id, float *temperature);
void signal_handler(int signal);

// Signal handler for graceful exit
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
    exit(0);
}

// Function to discover DS18B20 sensors
int discover_sensors() {
    char dir_path[MAX_LINE_LENGTH];
    snprintf(dir_path, sizeof(dir_path), "%s", W1_DEVICES_DIR);

    DIR *dir = opendir(dir_path);
    if (dir == NULL) {
        perror("opendir failed");
        return -1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            if (num_sensors < MAX_SENSORS) {
                strncpy(sensors[num_sensors].id, entry->d_name, MAX_SENSOR_ID_LENGTH - 1);
                sensors[num_sensors].id[MAX_SENSOR_ID_LENGTH - 1] = '\0'; // Ensure null termination
                snprintf(sensors[num_sensors].path, sizeof(sensors[num_sensors].path), "%s%s/w1_slave", W1_DEVICES_DIR, entry->d_name);
                sensors[num_sensors].valid = 0; // Initialize valid flag
                num_sensors++;
            } else {
                fprintf(stderr, "Warning: Too many sensors found.  Ignoring %s\n", entry->d_name);
            }
        }
    }

    closedir(dir);
    return 0;
}

// Function to read temperature from a DS18B20 sensor
int read_temperature(const char *sensor_id, float *temperature) {
    char path[MAX_LINE_LENGTH];
    snprintf(path, sizeof(path), "%s%s/w1_slave", W1_DEVICES_DIR, sensor_id);

    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        perror("fopen failed");
        return -1;
    }

    char line1[MAX_LINE_LENGTH], line2[MAX_LINE_LENGTH];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Check for CRC error
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    // Extract temperature data
    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Discover sensors
    if (discover_sensors() != 0) {
        fprintf(stderr, "Sensor discovery failed.\n");
        return 1;
    }

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Please check connections.\n");
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < num_sensors; i++) {
            float temperature;
            if (read_temperature(sensors[i].id, &temperature) == 0) {
                printf("Sensor %s: %.2f °C\n", sensors[i].id, temperature);
                sensors[i].valid = 1; // Mark as valid
            } else {
                fprintf(stderr, "Failed to read temperature from sensor %s\n", sensors[i].id);
                sensors[i].valid = 0; // Mark as invalid
            }
        }

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// HTU21D I2C address
#define HTU21D_ADDR 0x40

// HTU21D commands
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a single byte from the I2C device
int read_byte(int fd, uint8_t *data) {
    if (read(fd, data, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to write a single byte to the I2C device
int write_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read temperature from HTU21D
float read_temperature(int fd) {
    uint8_t msb, lsb;
    uint16_t raw_temp;
    float temperature;

    // Trigger temperature measurement
    if (write_byte(fd, TRIGGER_TEMP_MEASURE) < 0) {
        fprintf(stderr, "Error triggering temperature measurement\n");
        return -1.0;
    }

    // Wait for measurement to complete (at least 50ms)
    usleep(50000);

    // Read temperature data
    if (read_byte(fd, &msb) < 0) return -1.0;
    if (read_byte(fd, &lsb) < 0) return -1.0;

    raw_temp = (msb << 8) | lsb;

    // Check status bits (bits 15 and 14 of raw_temp)
    int status = (raw_temp >> 12) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Error: Status bits indicate an error (%d)\n", status);
        return -1.0;
    }

    // Convert raw temperature to Celsius
    temperature = -46.85 + 175.72 * ((float)raw_temp / 65536.0);

    return temperature;
}

// Function to read humidity from HTU21D
float read_humidity(int fd) {
    uint8_t msb, lsb;
    uint16_t raw_humidity;
    float humidity;

    // Trigger humidity measurement
    if (write_byte(fd, TRIGGER_HUMID_MEASURE) < 0) {
        fprintf(stderr, "Error triggering humidity measurement\n");
        return -1.0;
    }

    // Wait for measurement to complete (at least 50ms)
    usleep(50000);

    // Read humidity data
    if (read_byte(fd, &msb) < 0) return -1.0;
    if (read_byte(fd, &lsb) < 0) return -1.0;

    raw_humidity = (msb << 8) | lsb;

    // Check status bits (bits 15 and 14 of raw_humidity)
    int status = (raw_humidity >> 12) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Error: Status bits indicate an error (%d)\n", status);
        return -1.0;
    }

    // Convert raw humidity to relative humidity
    humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);

    return humidity;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c("/dev/i2c-1", HTU21D_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        float temperature, humidity;

        // Read temperature
        temperature = read_temperature(i2c_fd);
        if (temperature < -200.0) {
            fprintf(stderr, "Error reading temperature\n");
        } else {
            printf("Temperature: %.2f °C\n", temperature);
        }

        // Read humidity
        humidity = read_humidity(i2c_fd);
        if (humidity < -1.0) {
            fprintf(stderr, "Error reading humidity\n");
        } else {
            printf("Humidity: %.2f %%\n", humidity);
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup (should not reach here due to the signal handler)
    close(i2c_fd);
    return 0;
}

