#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        // Reset ADXL345 (set POWER_CTL to 0)
        uint8_t reset_value = 0x00;
        if (write(i2c_fd, &reset_value, 1) != 1) {
            perror("Error writing to I2C device");
        }
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from ADXL345
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = read_register(fd, ADXL345_DATAX0);
    x1 = read_register(fd, ADXL345_DATAX1);
    y0 = read_register(fd, ADXL345_DATAY0);
    y1 = read_register(fd, ADXL345_DATAY1);
    z0 = read_register(fd, ADXL345_DATAZ0);
    z1 = read_register(fd, ADXL345_DATAZ1);

    if (x0 == -1 || x1 == -1 || y0 == -1 || y1 == -1 || z0 == -1 || z1 == -1) {
        return -1; // Indicate error
    }

    *x = (int16_t)((x1 << 8) | x0);
    *y = (int16_t)((y1 << 8) | y0);
    *z = (int16_t)((z1 << 8) | z0);

    return 0; // Indicate success
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345 (set POWER_CTL to measure mode)
    if (write_register(i2c_fd, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error initializing ADXL345\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;

        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        usleep(100000); // 0.1 seconds
    }

    return 0;
}

