        // Wait for 0.1 seconds
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&ts, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");

    return 0;
}

