#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for DHT22 sensors
#define DHT22_GPIO_1 17
#define DHT22_GPIO_2 22
#define DHT22_GPIO_3 23
#define DHT22_GPIO_4 24

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int error;
} DHT22Data;

// Function prototypes
DHT22Data readDHT22(int gpio);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from a DHT22 sensor
DHT22Data readDHT22(int gpio) {
    DHT22Data data;
    data.temperature = -999.0; // Initialize with an invalid value
    data.humidity = -999.0;    // Initialize with an invalid value
    data.error = -1;           // Initialize with an error

    int i;
    int bit;
    int byte;
    int data_bits[40];

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed delay to 30 microseconds

    gpioSetMode(gpio, PI_INPUT);

    // Read data bits
    for (i = 0; i < 40; i++) {
        // Wait for low
        int count = 0;
        while (gpioRead(gpio) == 0) {
            count++;
            if (count > 1000) {
                data.error = -2; // Timeout error
                return data;
            }
            gpioDelay(1);
        }

        // Wait for high
        count = 0;
        while (gpioRead(gpio) == 1) {
            count++;
            if (count > 1000) {
                data.error = -2; // Timeout error
                return data;
            }
            gpioDelay(1);
        }

        // Determine bit value
        if (count > 40) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // Convert bits to bytes
    unsigned int raw_humidity = 0;
    unsigned int raw_temperature = 0;
    unsigned int raw_checksum = 0;

    for (i = 0; i < 16; i++) {
        byte = 0;
        for (bit = 0; bit < 8; bit++) {
            byte <<= 1;
            byte |= data_bits[i * 8 + bit];
        }

        if (i < 2) {
            raw_humidity <<= 8;
            raw_humidity |= byte;
        } else if (i < 4) {
            raw_temperature <<= 8;
            raw_temperature |= byte;
        } else {
            raw_checksum <<= 8;
            raw_checksum |= byte;
        }
    }

    // Calculate checksum
    unsigned int calculated_checksum = (raw_humidity & 0xFF) + (raw_humidity >> 8) + (raw_temperature & 0xFF) + (raw_temperature >> 8);

    // Verify checksum
    if ((raw_checksum & 0xFF) != (calculated_checksum & 0xFF)) {
        data.error = -3; // Checksum error
        return data;
    }

    // Convert data to temperature and humidity
    data.humidity = (float)((raw_humidity >> 8) | (raw_humidity << 8)) / 10.0;
    data.temperature = (float)((raw_temperature >> 8) | (raw_temperature << 8)) / 10.0;
    data.error = 0; // Success

    return data;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read data from DHT22 sensors
        DHT22Data data1 = readDHT22(DHT22_GPIO_1);
        DHT22Data data2 = readDHT22(DHT22_GPIO_2);
        DHT22Data data3 = readDHT22(DHT22_GPIO_3);
        DHT22Data data4 = readDHT22(DHT22_GPIO_4);

        // Print sensor data
        printf("Sensor 1 (GPIO %d): ", DHT22_GPIO_1);
        if (data1.error == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", data1.temperature, data1.humidity);
        } else {
            printf("Error: %d\n", data1.error);
        }

        printf("Sensor 2 (GPIO %d): ", DHT22_GPIO_2);
        if (data2.error == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", data2.temperature, data2.humidity);
        } else {
            printf("Error: %d\n", data2.error);
        }

        printf("Sensor 3 (GPIO %d): ", DHT22_GPIO_3);
        if (data3.error == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", data3.temperature, data3.humidity);
        } else {
            printf("Error: %d\n", data3.error);
        }

        printf("Sensor 4 (GPIO %d): ", DHT22_GPIO_4);
        if (data4.error == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", data4.temperature, data4.humidity);
        } else {
            printf("Error: %d\n", data4.error);
        }

        printf("\n");

        // Wait for 2 seconds
        sleep(2);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

