// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Main loop to control PWM outputs
    while (program_running) {
        // Set PWM duty cycle for PWM_PIN_1
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle (0-255 range)
        printf("PWM_PIN_1: 128\n");

        // Set PWM duty cycle for PWM_PIN_2
        gpioPWM(PWM_PIN_2, 192); // 75% duty cycle (0-255 range)
        printf("PWM_PIN_2: 192\n");

        // Set PWM duty cycle for PWM_PIN_3
        gpioPWM(PWM_PIN_3, 64);  // 25% duty cycle (0-255 range)
        printf("PWM_PIN_3: 64\n");

        // Wait for 0.5 seconds
        time_sleep(0.5);
    }

    // Stop PWM on all pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

