        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Main loop
    while (!terminate) {
        // Generate PWM signal (50% duty cycle)
        gpioPWM(PWM_GPIO, PWM_RANGE / 2);

        // Print the current state
        printf("PWM GPIO %d: %d\n", PWM_GPIO, gpioRead(PWM_GPIO));

        // Wait for 20 milliseconds
        gpioDelay(20000); // Delay in microseconds
    }

    // Clean up and terminate pigpio
    gpioPWM(PWM_GPIO, 0); // Stop PWM signal
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

