#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the TCS34725 sensor
int init_tcs34725(int fd) {
    // Enable the sensor (power on and enable RGBC)
    uint8_t enable_value = 0x03; // PON (power on) and AEN (RGBC enable)
    if (write(fd, &enable_value, 1) != 1) {
        perror("Failed to write to TCS34725_ENABLE");
        return -1;
    }

    // Set integration time (ATIME).  2.4ms * 256 = 62ms
    uint8_t atime_value = 0xEB; // 2.4ms integration time
    if (write(fd, &atime_value, 1) != 1) {
        perror("Failed to write to TCS34725_ATIME");
        return -1;
    }

    return 0;
}

// Function to read a register from the TCS34725
int read_register(int fd, uint8_t reg_addr, uint8_t *value) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the TCS34725
int read_16bit_value(int fd, uint8_t reg_addr, uint16_t *value) {
    uint8_t buffer[2];

    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read 16-bit value");
        return -1;
    }

    *value = (buffer[1] << 8) | buffer[0];
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (init_tcs34725(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize TCS34725 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop to read and print sensor data
    while (1) {
        uint16_t clear, red, green, blue;

        // Read the clear, red, green, and blue values
        if (read_16bit_value(i2c_fd, TCS34725_CDATA, &clear) != 0) {
            fprintf(stderr, "Error reading clear data.\n");
            continue; // Skip to the next iteration
        }
        if (read_16bit_value(i2c_fd, TCS34725_RDATA, &red) != 0) {
            fprintf(stderr, "Error reading red data.\n");
            continue;
        }
        if (read_16bit_value(i2c_fd, TCS34725_GDATA, &green) != 0) {
            fprintf(stderr, "Error reading green data.\n");
            continue;
        }
        if (read_16bit_value(i2c_fd, TCS34725_BDATA, &blue) != 0) {
            fprintf(stderr, "Error reading blue data.\n");
            continue;
        }

        // Print the sensor data
        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);

        // Wait for 0.2 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 0.2 seconds
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_18 18
#define GPIO_PIN_21 21
#define GPIO_PIN_22 22

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_18, *line_21, *line_22;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (line_21) {
        gpiod_line_release(line_21);
    }
    if (line_22) {
        gpiod_line_release(line_22);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for each pin
    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    line_21 = gpiod_chip_get_line(chip, GPIO_PIN_21);
    line_22 = gpiod_chip_get_line(chip, GPIO_PIN_22);

    if (!line_18 || !line_21 || !line_22) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_18, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line for output (18)");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line_21, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line for output (21)");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line_22, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line for output (22)");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial state to LOW
    if (gpiod_line_set_value(line_18, 0) < 0) {
        perror("Error setting GPIO line value (18)");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line_21, 0) < 0) {
        perror("Error setting GPIO line value (21)");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line_22, 0) < 0) {
        perror("Error setting GPIO line value (22)");
        gpiod_chip_close(chip);
        return 1;
    }

    // Report initial state
    printf("GPIO 18: LOW\n");
    printf("GPIO 21: LOW\n");
    printf("GPIO 22: LOW\n");

    // Wait for 5 seconds
    sleep(5);

    // Set GPIO 18 to HIGH
    if (gpiod_line_set_value(line_18, 1) < 0) {
        perror("Error setting GPIO line value (18)");
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 18: HIGH\n");

    // Wait for 2 seconds
    sleep(2);

    // Set GPIO 21 to HIGH
    if (gpiod_line_set_value(line_21, 1) < 0) {
        perror("Error setting GPIO line value (21)");
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 21: HIGH\n");

    // Wait for 2 seconds
    sleep(2);

    // Set GPIO 22 to HIGH
    if (gpiod_line_set_value(line_22, 1) < 0) {
        perror("Error setting GPIO line value (22)");
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 22: HIGH\n");

    // Wait for 5 seconds
    sleep(5);

    // Release GPIO lines
    gpiod_line_release(line_18);
    gpiod_line_release(line_21);
    gpiod_line_release(line_22);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILE "image.jpg"

struct buffer {
    void   *start;
    size_t  length;
};

static int                  fd = -1;
static struct buffer         *buffers = NULL;
static unsigned int           n_buffers = 0;

static void errno_exit(const char * s)
{
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (fd != -1) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (munmap(buffers[i].start, buffers[i].length) == -1) {
                fprintf(stderr, "munmap failed\n");
            }
        }
        free(buffers);
        close(fd);
    }
    exit(0);
}

int main(void)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;
    FILE *fp;
    time_t rawtime;
    struct tm * timeinfo;
    char filename[80];

    signal(SIGINT, signal_handler);

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", DEVICE_NAME, errno, strerror(errno));
        return 1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP error\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming i/o\n");
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT error\n");
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));

    req.count = 4; // Request 4 buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS error\n");
        close(fd);
        return 1;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return 1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QUERYBUF error\n");
            close(fd);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL /* start anywhere */,
                                      buf.length,
                                      PROT_READ | PROT_WRITE /* required */,
                                      MAP_SHARED /* recommended */,
                                      fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "mmap failed\n");
            close(fd);
            return 1;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QBUF error\n");
            close(fd);
            return 1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON error\n");
        close(fd);
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF error\n");
        close(fd);
        return 1;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.jpg", timeinfo);

    fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file for writing\n");
        close(fd);
        return 1;
    }

    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
    fclose(fp);

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF error\n");
        close(fd);
        return 1;
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMOFF error\n");
        close(fd);
        return 1;
    }

    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            fprintf(stderr, "munmap failed\n");
        }
    }

    free(buffers);
    close(fd);

    printf("Image saved to %s\n", filename);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_PIN_1 22
#define GPIO_PIN_2 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_PIN_1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_2, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Toggle the state of GPIO 22
        gpioWrite(GPIO_PIN_1, !gpioRead(GPIO_PIN_1));

        // Toggle the state of GPIO 27
        gpioWrite(GPIO_PIN_2, !gpioRead(GPIO_PIN_2));

        // Report the current states
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, gpioRead(GPIO_PIN_1), GPIO_PIN_2, gpioRead(GPIO_PIN_2));

        // Wait for 0.01 seconds
        gpioDelay(10000); // 10000 microseconds = 0.01 seconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Define the I2C address of the SSD1306
#define SSD1306_I2C_ADDR 0x3C

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Function to write a command to the SSD1306
void ssd1306_write_command(unsigned char command) {
    unsigned char buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write command to SSD1306");
    }
}

// Function to write data to the SSD1306
void ssd1306_write_data(unsigned char data) {
    unsigned char buffer[2];
    buffer[0] = 0x40; // Control byte: data
    buffer[1] = data;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write data to SSD1306");
    }
}

// Function to initialize the SSD1306
void ssd1306_init() {
    ssd1306_write_command(0xAE); // Display off
    ssd1306_write_command(0xD5); // Set display clock divide ratio/oscillator frequency
    ssd1306_write_command(0x80); // --ratio
    ssd1306_write_command(0xA8); // Set multiplex ratio
    ssd1306_write_command(0x3F); // --ratio
    ssd1306_write_command(0xD3); // Set display offset
    ssd1306_write_command(0x00); // --offset
    ssd1306_write_command(0x40); // Set start line address
    ssd1306_write_command(0x8D); // Charge pump setting
    ssd1306_write_command(0x14); // --enable
    ssd1306_write_command(0x20); // Set memory addressing mode
    ssd1306_write_command(0x00); // --horizontal addressing mode
    ssd1306_write_command(0xA1); // Set segment re-map
    ssd1306_write_command(0xC8); // Set COM output scan direction
    ssd1306_write_command(0xDA); // Set COM pins hardware configuration
    ssd1306_write_command(0x12); // --alternative
    ssd1306_write_command(0x81); // Set contrast control
    ssd1306_write_command(0xCF); // --contrast
    ssd1306_write_command(0xD9); // Set pre-charge period
    ssd1306_write_command(0xF1); // --period
    ssd1306_write_command(0xDB); // Set VCOM deselect level
    ssd1306_write_command(0x40); // --level
    ssd1306_write_command(0xA4); // Display all points off
    ssd1306_write_command(0xA6); // Set normal display
    ssd1306_write_command(0xAF); // Display on
}

// Function to clear the SSD1306 display
void ssd1306_clear_display() {
    for (int i = 0; i < 8; i++) {
        ssd1306_write_command(0xB0 + i); // Set page address
        ssd1306_write_command(0x00);     // Set lower column address
        ssd1306_write_command(0x10);     // Set higher column address
        for (int j = 0; j < 128; j++) {
            ssd1306_write_data(0x00); // Write 0 to clear the pixel
        }
    }
}

// Function to display a string on the SSD1306
void ssd1306_display_string(const char *string) {
    ssd1306_write_command(0x01); // Set column address
    ssd1306_write_command(0x00); // Lower column address
    ssd1306_write_command(0x10); // Higher column address
    ssd1306_write_command(0x02); // Set page address

    for (int i = 0; string[i] != '\0'; i++) {
        // Simple character mapping (ASCII 32-126) to 5x8 font
        // This is a placeholder; a real implementation would use a font table
        for (int j = 0; j < 5; j++) {
            ssd1306_write_data(0xFF); // Placeholder data
        }
        ssd1306_write_command(0x10); // Increment column
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the I2C device file
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the SSD1306
    ssd1306_init();
    ssd1306_clear_display();

    // Main loop
    while (1) {
        // Get the current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Format the time string
        char time_string[20];
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Display the time on the SSD1306
        ssd1306_clear_display();
        ssd1306_display_string(time_string);

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    return 0;
}

