#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to trigger the HC-SR04
void trigger_hc_sr04()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance in centimeters
float measure_distance()
{
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    trigger_hc_sr04();

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate the pulse duration
    diff_tick = end_tick - start_tick;

    // Calculate the distance
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = measure_distance();

        if (distance >= 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else
        {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(200); // Wait 0.2 seconds
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

