#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_27 27

// Chip name (usually gpiochip0)
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *line_17 = NULL;
struct gpiod_line *line_27 = NULL;

// Function prototypes
int gpio_export(int gpio);
int gpio_unexport(int gpio);
int gpio_set_direction(int gpio, const char *direction);
int gpio_set_value(int gpio, int value);
int gpio_get_value(int gpio);
int gpio_set_output(int gpio, int value);
int gpio_set_input(int gpio);

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Structure to hold GPIO configuration
typedef struct {
    int gpio;
    const char *direction;
} gpio_config_t;

// Array of GPIO configurations
gpio_config_t gpio_configs[] = {
    {GPIO_17, "out"},
    {GPIO_27, "out"}
};

int main() {
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return 1;
    }

    // Export GPIO pins
    for (i = 0; i < sizeof(gpio_configs) / sizeof(gpio_configs[0]); i++) {
        if (gpio_export(gpio_configs[i].gpio) != 0) {
            fprintf(stderr, "Error exporting GPIO %d\n", gpio_configs[i].gpio);
            goto cleanup;
        }
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line_17 || !line_27) {
        fprintf(stderr, "Error getting GPIO line\n");
        goto cleanup;
    }

    // Set GPIO directions
    for (i = 0; i < sizeof(gpio_configs) / sizeof(gpio_configs[0]); i++) {
        if (gpio_set_direction(gpio_configs[i].gpio, gpio_configs[i].direction) != 0) {
            fprintf(stderr, "Error setting direction for GPIO %d\n", gpio_configs[i].gpio);
            goto cleanup;
        }
    }

    // Set GPIO values
    if (gpio_set_output(GPIO_17, 1) != 0) {
        fprintf(stderr, "Error setting output for GPIO 17\n");
        goto cleanup;
    }
    if (gpio_set_output(GPIO_27, 0) != 0) {
        fprintf(stderr, "Error setting output for GPIO 27\n");
        goto cleanup;
    }

    // Print GPIO states
    printf("GPIO 17: %d\n", gpio_get_value(GPIO_17));
    printf("GPIO 27: %d\n", gpio_get_value(GPIO_27));

    // Cleanup and exit
    goto cleanup;

cleanup:
    // Unexport GPIO pins
    for (i = 0; i < sizeof(gpio_configs) / sizeof(gpio_configs[0]); i++) {
        gpio_unexport(gpio_configs[i].gpio);
    }

    // Release GPIO lines
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

// Function to export a GPIO pin
int gpio_export(int gpio) {
    char buffer[64];
    int fd;

    fd = gpiod_chip_get_line_fd(chip, gpio);
    if (fd < 0) {
        fprintf(stderr, "Error getting line fd for GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int gpio) {
    char buffer[64];
    FILE *fp;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/unexport");
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening unexport file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", gpio);
    fclose(fp);
    return 0;
}

// Function to set the direction of a GPIO pin
int gpio_set_direction(int gpio, const char *direction) {
    char buffer[64];
    FILE *fp;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/direction", gpio);
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening direction file for GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s", direction);
    fclose(fp);
    return 0;
}

// Function to set the value of a GPIO pin
int gpio_set_value(int gpio, int value) {
    char buffer[64];
    FILE *fp;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio);
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening value file for GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", value);
    fclose(fp);
    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int gpio) {
    char buffer[64];
    FILE *fp;
    int value;

    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d/value", gpio);
    fp = fopen(buffer, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening value file for GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Error reading value from GPIO %d\n", gpio);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return value;
}

// Function to set a GPIO as output and set its value
int gpio_set_output(int gpio, int value) {
    if (gpio_set_direction(gpio, "out") != 0) {
        return -1;
    }
    if (gpio_set_value(gpio, value) != 0) {
        return -1;
    }
    return 0;
}

// Function to set a GPIO as input
int gpio_set_input(int gpio) {
    if (gpio_set_direction(gpio, "in") != 0) {
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    int i;

    printf("Caught signal %d, cleaning up...\n", sig);

    // Unexport GPIO pins
    for (i = 0; i < sizeof(gpio_configs) / sizeof(gpio_configs[0]); i++) {
        gpio_unexport(gpio_configs[i].gpio);
    }

    // Release GPIO lines
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_LINE 17 // Line number on the chip

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

int main()
{
    int ret;
    int value;

    // Register signal handlers for graceful shutdown
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_LINE, strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO line value to 1
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value to 1: %s\n", GPIO_LINE, strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Read GPIO line value
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d value: %s\n", GPIO_LINE, strerror(-value));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Print the GPIO line value
    printf("GPIO %d value: %d\n", GPIO_LINE, value);

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

