           gpiod_line_get_value(gpio_lines.line5),
           gpiod_line_get_value(gpio_lines.line6),
           gpiod_line_get_value(gpio_lines.line21),
           gpiod_line_get_value(gpio_lines.line22),
           gpiod_line_get_value(gpio_lines.line23),
           gpiod_line_get_value(gpio_lines.line24));

    // Wait for user input
    printf("Press Enter to exit and cleanup...\n");
    getchar();

cleanup:
    // Release GPIO lines
    if (gpio_lines.line1) gpiod_line_release(gpio_lines.line1);
    if (gpio_lines.line4) gpiod_line_release(gpio_lines.line4);
    if (gpio_lines.line5) gpiod_line_release(gpio_lines.line5);
    if (gpio_lines.line6) gpiod_line_release(gpio_lines.line6);
    if (gpio_lines.line21) gpiod_line_release(gpio_lines.line21);
    if (gpio_lines.line22) gpiod_line_release(gpio_lines.line22);
    if (gpio_lines.line23) gpiod_line_release(gpio_lines.line23);
    if (gpio_lines.line24) gpiod_line_release(gpio_lines.line24);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILE "image.jpg"

typedef struct {
    void   *start;
    size_t  length;
} buffer;

static int                  fd = -1;
static buffer              *buffers = NULL;
static unsigned int         n_buffers = 0;

static void errno_exit(const char * s)
{
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static void signal_handler(int signal)
{
    printf("Caught signal %d, exiting...\n", signal);

    if (fd != -1) {
        /* Stop streaming */
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
            fprintf(stderr, "VIDIOC_STREAMOFF failed: %d, %s\n", errno, strerror(errno));
        }

        /* Unmap buffers */
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (-1 == munmap(buffers[i].start, buffers[i].length)) {
                fprintf(stderr, "munmap failed: %d, %s\n", errno, strerror(errno));
            }
        }

        /* Free buffers */
        free(buffers);

        /* Close device */
        if (-1 == close(fd)) {
            fprintf(stderr, "close failed: %d, %s\n", errno, strerror(errno));
        }
        fd = -1;
    }

    exit(0);
}

int main()
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;
    enum v4l2_buf_type type;

    /* Install signal handler */
    signal(SIGINT, signal_handler);

    /* Open device */
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (-1 == fd) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", DEVICE_NAME, errno, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Check capabilities */
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %d, %s\n", errno, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set image format */
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %d, %s\n", errno, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Request buffers */
    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %d, %s\n", errno, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    n_buffers = req.count;

    /* Map buffers */
    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            fprintf(stderr, "mmap failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
    }

    /* Queue buffers */
    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
    }

    /* Start streaming */
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %d, %s\n", errno, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Capture loop */
    while (1) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            fprintf(stderr, "VIDIOC_DQBUF failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        // Save the captured image to a file
        FILE *fp = fopen(IMAGE_FILE, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file for writing: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
        fclose(fp);

        printf("Image saved to %s\n", IMAGE_FILE);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        usleep(50000); // 0.05 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data);
int bme280_init(int fd);
int bme280_read_data(int fd, float *temperature, float *pressure, float *humidity);
void signal_handler(int signal);
int read_calibration_data(int fd, struct bme280_calib_data *calib);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// BME280 initialization function
int bme280_init(int fd) {
    // Check the device ID
    uint8_t id;
    if (i2c_read_bytes(fd, BME280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Error reading BME280 ID\n");
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Incorrect BME280 ID: 0x%02X\n", id);
        return -1;
    }

    // Read calibration data
    if (read_calibration_data(fd, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2c_write_byte(fd, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error writing humidity control register\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2c_write_byte(fd, BME280_REG_CTRL_MEAS, 0x27) != 0) { //0b00100111
        fprintf(stderr, "Error writing control register\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data(int fd, struct bme280_calib_data *calib) {
    uint8_t data[26];
    if (i2c_read_bytes(fd, BME280_REG_CALIB_00, data, 26) != 0) {
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib->dig_H1 = data[25];

    uint8_t data_h[7];
    if (i2c_read_bytes(fd, BME280_REG_CALIB_26, data_h, 7) != 0) {
        return -1;
    }

    calib->dig_H2 = (int16_t)data_h[0] | ((int16_t)data_h[1] << 8);
    calib->dig_H3 = data_h[2];
    calib->dig_H4 = (int16_t)((data_h[3] << 4) | (data_h[4] & 0x0F));
    calib->dig_H5 = (int16_t)((data_h[5] << 4) | (data_h[4] >> 4));
    calib->dig_H6 = (int8_t)data_h[6];

    return 0;
}

// BME280 data reading function
int bme280_read_data(int fd, float *temperature, float *pressure, float *humidity) {
    uint8_t data[8];
    int32_t raw_temp, raw_press, raw_hum;

    // Read temperature, pressure, and humidity data
    if (i2c_read_bytes(fd, BME280_REG_PRESS_MSB, data, 8) != 0) {
        fprintf(stderr, "Error reading data registers\n");
        return -1;
    }

    raw_press = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    raw_temp = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;
    raw_hum = (int32_t)data[6] << 8 | (int32_t)data[7];

    // Compensate temperature
    double var1 = (raw_temp / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temp / 131072.0 - calib.dig_T1 / 8192.0) *
                   (raw_temp / 131072.0 - calib.dig_T1 / 8192.0)) *
                  calib.dig_T3;
    double t_fine = var1 + var2;
    *temperature = (t_fine / 5120.0);

    // Compensate pressure
    double var3 = t_fine / 2.0 - 64000.0;
    double var4 = var3 * var3 * calib.dig_P6 / 32768.0;
    double var5 = var4 + var3 * calib.dig_P5 * 2.0;
    double var6 = var5 / 4.0 + calib.dig_P4 * 65536.0;
    double var7 = calib.dig_P3 * var3 * var3 / 524288.0;
    double var8 = calib.dig_P2 * var3 / 524288.0;
    double var9 = 1.0 + (var7 + var8 + var6) / 32768.0;
    double pressure_val = 1048576.0 - raw_press;
    pressure_val = (pressure_val - var6 / 4096.0) * 6250.0 / var9;
    var3 = calib.dig_P9 * pressure_val * pressure_val / 2147483648.0;
    var4 = pressure_val * calib.dig_P8 / 32768.0;
    *pressure = pressure_val + (var3 + var4 + calib.dig_P7) / 16.0;

    // Compensate humidity
    double var_H = t_fine - 76800.0;
    var_H = (raw_hum - (calib.dig_H4 * 64.0 + calib.dig_H5 / 16384.0 * var_H)) *
            (calib.dig_H2 / 65536.0 * (1.0 + calib.dig_H6 / 67108864.0 * var_H *
                                       (1.0 + calib.dig_H3 / 67108864.0 * var_H)));
    *humidity = var_H * (1.0 - calib.dig_H1 * var_H / 524288.0);
    if (*humidity > 100.0)
        *humidity = 100.0;
    else if (*humidity < 0.0)
        *humidity = 0.0;

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    float temperature, pressure, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BME280 sensor
    if (bme280_init(i2c_fd) != 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("BME280 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        if (bme280_read_data(i2c_fd, &temperature, &pressure, &humidity) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Print data to standard output
            printf("%s - Temperature: %.2f °C, Pressure: %.2f hPa, Humidity: %.2f %%\n",
                   timestamp, temperature, pressure, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000   // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define CONFIG_DR_128SPS 0x0060    // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_ACTV_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON_LATCH 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int read_ads1115(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure ADS1115 for single conversion
        uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;

        if (write_ads1115(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Error configuring ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion result
        uint16_t conversion;
        if (read_ads1115(i2c_fd, ADS1115_REG_CONVERT, &conversion) < 0) {
            fprintf(stderr, "Error reading conversion result\n");
            close(i2c_fd);
            return 1;
        }

        // Print the reading
        printf("ADC Value: %d\n", conversion);

        // Wait 200ms
        usleep(200000);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define GPIO_LINE 4

static struct gpiod_chip *chip;
static struct gpiod_line *line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_set_value(line, 0); // Set GPIO to LOW
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    int ret;
    int i;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO state
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }

        // Print GPIO state
        printf("GPIO %d is now %s\n", GPIO_PIN, gpiod_line_get_value(line) ? "HIGH" : "LOW");

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup (in case of error)
    gpiod_line_set_value(line, 0); // Set GPIO to LOW
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (set PWR_MGMT_1 to 0)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (write(fd, data, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    data[0] = ACCEL_CONFIG;
    data[1] = 0x00;
    if (write(fd, data, 2) != 2) {
        perror("Failed to write to ACCEL_CONFIG");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    uint8_t reg = ACCEL_XOUT_H;

    // Write the starting register address to the I2C device
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    // Read 6 bytes of accelerometer data
    if (read(fd, data, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    // Combine high and low bytes to form 16-bit signed integers
    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed. Check I2C connection.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer(i2c_fd, &x, &y, &z) == 0) {
            // Print accelerometer data
            printf("Accelerometer X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        // Wait for 0.01 seconds
        usleep(10000); // 10000 microseconds = 10 milliseconds = 0.01 seconds
    }

    return 0;
}

