// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define HD44780_ADDR 0x27 // Replace with your HD44780 I2C address

// Define LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20
#define LCD_SETCGRAMADDR 0x40
#define LCD_SETDDRAMADDR 0x80

// Flags for display control
#define LCD_DISPLAYON 0x04
#define LCD_CURSORON 0x02
#define LCD_BLINKON 0x01

// Flags for entry mode
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// Flags for function set
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// LCD line number
#define LCD_LINE1 0x00
#define LCD_LINE2 0x40

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Function to write a command to the LCD
void lcd_command(int fd, unsigned char cmd) {
  unsigned char data_u, data_l;
  unsigned char data_t[4];
  data_u = (cmd & 0xF0);
  data_l = ((cmd << 4) & 0xF0);

  data_t[0] = data_u | 0x0C;  //en=1, rs=0
  data_t[1] = data_u | 0x08;  //en=0, rs=0
  data_t[2] = data_l | 0x0C;  //en=1, rs=0
  data_t[3] = data_l | 0x08;  //en=0, rs=0

  if (write(fd, data_t, 4) != 4) {
    perror("Failed to write command to I2C device");
  }
}

// Function to write data to the LCD
void lcd_data(int fd, unsigned char data) {
  unsigned char data_u, data_l;
  unsigned char data_t[4];
  data_u = (data & 0xF0);
  data_l = ((data << 4) & 0xF0);

  data_t[0] = data_u | 0x0D;  //en=1, rs=1
  data_t[1] = data_u | 0x09;  //en=0, rs=1
  data_t[2] = data_l | 0x0D;  //en=1, rs=1
  data_t[3] = data_l | 0x09;  //en=0, rs=1

  if (write(fd, data_t, 4) != 4) {
    perror("Failed to write data to I2C device");
  }
}

// Function to initialize the LCD
void lcd_init(int fd) {
  lcd_command(fd, 0x33); // Initialize
  lcd_command(fd, 0x32); // Initialize
  lcd_command(fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
  lcd_command(fd, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSORON | LCD_BLINKON);
  lcd_command(fd, LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT);
  lcd_command(fd, LCD_CLEARDISPLAY);
  usleep(2000); // Clear display command needs a long delay
}

// Function to clear the LCD display
void lcd_clear(int fd) {
  lcd_command(fd, LCD_CLEARDISPLAY);
  usleep(2000); // Clear display command needs a long delay
}

// Function to set the cursor position
void lcd_set_cursor(int fd, unsigned char col, unsigned char row) {
  unsigned char addr;
  if (row == 0) {
    addr = 0x00 + col;
  } else {
    addr = 0x40 + col;
  }
  lcd_command(fd, LCD_SETDDRAMADDR | addr);
}

// Function to write a string to the LCD
void lcd_write_string(int fd, const char *str) {
  while (*str) {
    lcd_data(fd, *str++);
  }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
  printf("\nExiting program...\n");
  if (i2c_fd != -1) {
    close(i2c_fd);
  }
  exit(0);
}

int main() {
  // Register the signal handler
  signal(SIGINT, signal_handler);

  // Open the I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    return 1;
  }

  // Set the I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, HD44780_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Initialize the LCD
  lcd_init(i2c_fd);

  // Main loop
  while (1) {
    // Get the current time
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the time string
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Display the time on the LCD
    lcd_clear(i2c_fd);
    lcd_set_cursor(i2c_fd, 0, 0);
    lcd_write_string(i2c_fd, time_str);

    // Wait for 10 seconds
    sleep(10);
  }

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two I2C registers
int i2c_read_word(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main() {
    int i2c_fd;
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int retries = 3; // Number of retries for I2C initialization
    bool mpu6050_present = false;

    // Open I2C device
    while (retries > 0) {
        i2c_fd = open(i2c_device, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C device");
            retries--;
            sleep(1); // Wait before retrying
        } else {
            break; // I2C device opened successfully
        }
    }

    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device after multiple retries. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize MPU6050 (wake up the sensor)
    if (i2c_write_byte(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050. Check connection.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2c_write_byte(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer range.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    mpu6050_present = true;

    // Read accelerometer data
    for (int i = 0; i < 100; i++) {
        int16_t accel_x, accel_y, accel_z;

        if (i2c_read_word(i2c_fd, ACCEL_XOUT_H, &accel_x) < 0) {
            fprintf(stderr, "Failed to read accelerometer X data.\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        if (i2c_read_word(i2c_fd, ACCEL_YOUT_H, &accel_y) < 0) {
            fprintf(stderr, "Failed to read accelerometer Y data.\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        if (i2c_read_word(i2c_fd, ACCEL_ZOUT_H, &accel_z) < 0) {
            fprintf(stderr, "Failed to read accelerometer Z data.\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Print the raw accelerometer data
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
    }

    // Close I2C device
    close(i2c_fd);

    if (!mpu6050_present) {
        fprintf(stderr, "MPU6050 not detected after initialization.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_14 14
#define GPIO_15 15

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 14 and GPIO 15 as outputs
    gpioSetMode(GPIO_14, PI_OUTPUT);
    gpioSetMode(GPIO_15, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Toggle the state of GPIO 14
        int current_state = gpioRead(GPIO_14);
        int new_state = !current_state;
        gpioWrite(GPIO_14, new_state);
        printf("GPIO %d: %d\n", GPIO_14, new_state);

        // Toggle the state of GPIO 15
        current_state = gpioRead(GPIO_15);
        new_state = !current_state;
        gpioWrite(GPIO_15, new_state);
        printf("GPIO %d: %d\n", GPIO_15, new_state);

        // Wait for 5 seconds
        sleep(5);
    }

    // Terminate the pigpio library
    gpioTerminate();

    // Exit the program
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Change this to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SENSOR_POWER_PIN 4 // GPIO pin for sensor power control
#define SENSOR_READ_COMMAND 0x01 // Command to request sensor data
#define SENSOR_DATA_LENGTH 4 // Length of the sensor data in bytes
#define SENSOR_CHECKSUM_LENGTH 2 // Length of the checksum in bytes
#define SENSOR_CHECKSUM_POSITION (SENSOR_DATA_LENGTH + 1) // Position of the checksum in the received data
#define SENSOR_DATA_POSITION 1 // Position of the sensor data in the received data
#define SENSOR_DATA_START 2 // Position of the first byte of sensor data

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor_data(unsigned char *data);
int validate_checksum(const unsigned char *data);
int publish_data(const unsigned char *data);
void signal_handler(int signum);
int mqtt_connect_and_publish(const unsigned char *data);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to read sensor data via SPI
int read_sensor_data(unsigned char *data) {
    int i;
    char tx_buf[1];
    char rx_buf[SENSOR_DATA_LENGTH + SENSOR_CHECKSUM_LENGTH];

    // Send read command
    tx_buf[0] = SENSOR_READ_COMMAND;
    if (spiXfer(SPI_CHANNEL, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error: SPI write failed\n");
        return -1;
    }

    // Read sensor data and checksum
    if (spiXfer(SPI_CHANNEL, NULL, rx_buf, SENSOR_DATA_LENGTH + SENSOR_CHECKSUM_LENGTH) != 0) {
        fprintf(stderr, "Error: SPI read failed\n");
        return -1;
    }

    // Copy data to the provided buffer
    for (i = 0; i < SENSOR_DATA_LENGTH; i++) {
        data[i] = rx_buf[i];
    }

    return 0;
}

// Function to validate the checksum of the sensor data
int validate_checksum(const unsigned char *data) {
    unsigned char calculated_checksum = 0;
    unsigned char received_checksum = data[SENSOR_CHECKSUM_POSITION];
    int i;

    // Calculate checksum (simple XOR of all data bytes)
    for (i = SENSOR_DATA_POSITION; i < SENSOR_DATA_LENGTH + SENSOR_DATA_POSITION; i++) {
        calculated_checksum ^= data[i];
    }

    // Compare calculated checksum with received checksum
    if (calculated_checksum != received_checksum) {
        fprintf(stderr, "Error: Checksum validation failed\n");
        return -1;
    }

    return 0;
}

// Function to publish sensor data to MQTT broker
int publish_data(const unsigned char *data) {
    char payload[SENSOR_DATA_LENGTH * 2 + 1]; // Buffer to hold hexadecimal representation of the data
    int i;

    // Convert data to hexadecimal string
    for (i = 0; i < SENSOR_DATA_LENGTH; i++) {
        sprintf(payload + i * 2, "%02X", data[i]);
    }
    payload[SENSOR_DATA_LENGTH * 2] = '\0'; // Null-terminate the string

    // Publish the data to the MQTT broker
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: mosquitto_publish failed: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Function to connect to MQTT broker and publish data
int mqtt_connect_and_publish(const unsigned char *data) {
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: mosquitto_connect failed: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = publish_data(data);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: publish_data failed\n");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    return 0;
}

int main() {
    unsigned char sensor_data[SENSOR_DATA_LENGTH];
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin for sensor power as output
    gpioSetMode(SENSOR_POWER_PIN, PI_OUTPUT);
    gpioWrite(SENSOR_POWER_PIN, 1); // Power on the sensor

    // Initialize SPI
    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioWrite(SENSOR_POWER_PIN, 0); // Power off the sensor
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sensor data publishing started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate checksum
            if (validate_checksum(sensor_data) == 0) {
                // Publish data to MQTT broker
                if (mqtt_connect_and_publish(sensor_data) != 0) {
                    fprintf(stderr, "Error: Failed to publish data to MQTT broker\n");
                }
            } else {
                fprintf(stderr, "Error: Checksum validation failed, skipping publishing\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data, skipping publishing\n");
        }

        // Wait for 0.01 seconds
        gpioDelay(10000); // 10000 microseconds = 0.01 seconds
    }

    // Clean up
    spiClose(SPI_CHANNEL);
    gpioWrite(SENSOR_POWER_PIN, 0); // Power off the sensor
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

