#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

// Configuration structure
typedef struct {
    char mqtt_broker_address[100];
    int mqtt_broker_port;
    char mqtt_topic[100];
    int sensor_gpio_pin;
    int sensor_timeout_seconds;
} Config;

// Global variables
static volatile int running = 1;
static Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
int read_sensor(int gpio_pin);
int publish_message(const char *topic, const char *message, const char *broker_address, int broker_port);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "mqtt_broker_address") == 0) {
            strncpy(config->mqtt_broker_address, value, sizeof(config->mqtt_broker_address) - 1);
            config->mqtt_broker_address[sizeof(config->mqtt_broker_address) - 1] = '\0';
        } else if (strcmp(key, "mqtt_broker_port") == 0) {
            config->mqtt_broker_port = atoi(value);
        } else if (strcmp(key, "mqtt_topic") == 0) {
            strncpy(config->mqtt_topic, value, sizeof(config->mqtt_topic) - 1);
            config->mqtt_topic[sizeof(config->mqtt_topic) - 1] = '\0';
        } else if (strcmp(key, "sensor_gpio_pin") == 0) {
            config->sensor_gpio_pin = atoi(value);
        } else if (strcmp(key, "sensor_timeout_seconds") == 0) {
            config->sensor_timeout_seconds = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value from GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to publish message to MQTT broker
int publish_message(const char *topic, const char *message, const char *broker_address, int broker_port) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    MQTTClient_create(&client, broker_address, "sensor_reader", MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        return -1;
    }

    pubmsg.payload = message;
    pubmsg.payloadlen = strlen(message);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return -1;
    }

    MQTTClient_waitForCompletion(client, token, 1000);

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read configuration from file
    if (read_config("config.ini", &config) != 0) {
        fprintf(stderr, "Failed to read configuration. Exiting.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(config.sensor_gpio_pin, PI_INPUT);

    // Main loop
    while (running) {
        time_t start_time = time(NULL);
        int sensor_value = read_sensor(config.sensor_gpio_pin);

        if (sensor_value >= 0) {
            char message[50];
            snprintf(message, sizeof(message), "%d", sensor_value);

            if (publish_message(config.mqtt_topic, message, config.mqtt_broker_address, config.mqtt_broker_port) != 0) {
                fprintf(stderr, "Failed to publish message.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor value.\n");
        }

        time_t current_time = time(NULL);
        double elapsed_time = difftime(current_time, start_time);

        if (elapsed_time < config.sensor_timeout_seconds) {
            sleep(config.sensor_timeout_seconds - (int)elapsed_time);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
