#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int pigpio_init_result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Configure PWM on GPIO 18
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_GPIO);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Generate PWM signal (50% duty cycle)
        if (gpioPWM(PWM_GPIO, PWM_RANGE / 2) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_GPIO);
            break; // Exit loop on error
        }

        // Print the current state
        printf("PWM GPIO %d: %d\n", PWM_GPIO, PWM_RANGE / 2);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    gpioPWM(PWM_GPIO, 0); // Stop PWM signal
    gpioTerminate();       // Terminate pigpio

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

