    }

    end_tick = gpioTick();

    // Calculate the pulse duration in microseconds
    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = measure_distance();

        if (distance >= 0.0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else
        {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        gpioDelay(200000); // Wait 0.2 seconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

