#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration structure
typedef struct {
    char *mqtt_broker_address;
    int mqtt_broker_port;
    char *mqtt_topic;
    int i2c_address;
    int sensor_id;
    int read_interval_seconds;
    int timeout_seconds;
} Config;

// Global variables
static volatile int running = 1;
static Config config;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_config(const char *filename, Config *config);
int read_sensor_data(int i2c_handle);
int validate_sensor_data(int sensor_data);
int publish_data(int sensor_data);
void signal_handler(int signum);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "mqtt_broker_address") == 0) {
            config->mqtt_broker_address = strdup(value);
        } else if (strcmp(key, "mqtt_broker_port") == 0) {
            config->mqtt_broker_port = atoi(value);
        } else if (strcmp(key, "mqtt_topic") == 0) {
            config->mqtt_topic = strdup(value);
        } else if (strcmp(key, "i2c_address") == 0) {
            config->i2c_address = strtol(value, NULL, 0);
        } else if (strcmp(key, "sensor_id") == 0) {
            config->sensor_id = atoi(value);
        } else if (strcmp(key, "read_interval_seconds") == 0) {
            config->read_interval_seconds = atoi(value);
        } else if (strcmp(key, "timeout_seconds") == 0) {
            config->timeout_seconds = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle) {
    int sensor_data = i2cReadWordData(i2c_handle, 0); // Assuming register 0
    if (sensor_data < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", sensor_data);
        return -1;
    }
    return sensor_data;
}

// Function to validate sensor data
int validate_sensor_data(int sensor_data) {
    // Example validation: Check if the data is within a reasonable range
    if (sensor_data < 0 || sensor_data > 1000) {
        fprintf(stderr, "Invalid sensor data: %d\n", sensor_data);
        return -1;
    }
    return 0;
}

// Function to publish data to MQTT broker
int publish_data(int sensor_data) {
    char payload[64];
    snprintf(payload, sizeof(payload), "{\"sensor_id\": %d, \"sensor_data\": %d}", config.sensor_id, sensor_data);

    int ret = mosquitto_publish(mosq, NULL, config.mqtt_topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, exiting...\n");
}

// MQTT connect callback
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        printf("Connected to MQTT broker\n");
    } else {
        fprintf(stderr, "Connection failed: %s\n", mosquitto_connack_string(result));
    }
}

// MQTT disconnect callback
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    printf("Disconnected from MQTT broker\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Read configuration from file
    if (read_config("config.ini", &config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);

    int ret = mosquitto_connect(mosq, config.mqtt_broker_address, config.mqtt_broker_port, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int i2c_handle = i2cOpen(1, config.i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    while (running) {
        int sensor_data = read_sensor_data(i2c_handle);
        if (sensor_data >= 0) {
            if (validate_sensor_data(sensor_data) == 0) {
                if (publish_data(sensor_data) != 0) {
                    fprintf(stderr, "Error publishing data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(config.read_interval_seconds);
    }

    // Cleanup
    i2cClose(i2c_handle);
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    free(config.mqtt_broker_address);
    free(config.mqtt_topic);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

// Configuration structure
typedef struct {
    char mqtt_broker_address[100];
    int mqtt_broker_port;
    char mqtt_client_id[50];
    char mqtt_username[50];
    char mqtt_password[50];
    char mqtt_topic[100];
    int ads1115_address;
    int ads1115_channel;
    int ads1115_gain;
    int readings_to_publish;
} Config;

// Global variables
int i2c_handle;
MQTTClient client;
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename, Config *config);
int initialize_mqtt(const Config *config);
int publish_reading(const Config *config, float reading);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "mqtt_broker_address") == 0) {
            strncpy(config->mqtt_broker_address, value, sizeof(config->mqtt_broker_address) - 1);
        } else if (strcmp(key, "mqtt_broker_port") == 0) {
            config->mqtt_broker_port = atoi(value);
        } else if (strcmp(key, "mqtt_client_id") == 0) {
            strncpy(config->mqtt_client_id, value, sizeof(config->mqtt_client_id) - 1);
        } else if (strcmp(key, "mqtt_username") == 0) {
            strncpy(config->mqtt_username, value, sizeof(config->mqtt_username) - 1);
        } else if (strcmp(key, "mqtt_password") == 0) {
            strncpy(config->mqtt_password, value, sizeof(config->mqtt_password) - 1);
        } else if (strcmp(key, "mqtt_topic") == 0) {
            strncpy(config->mqtt_topic, value, sizeof(config->mqtt_topic) - 1);
        } else if (strcmp(key, "ads1115_address") == 0) {
            config->ads1115_address = atoi(value);
        } else if (strcmp(key, "ads1115_channel") == 0) {
            config->ads1115_channel = atoi(value);
        } else if (strcmp(key, "ads1115_gain") == 0) {
            config->ads1115_gain = atoi(value);
        } else if (strcmp(key, "readings_to_publish") == 0) {
            config->readings_to_publish = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize MQTT
int initialize_mqtt(const Config *config) {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    MQTTClient_create(&client, config->mqtt_client_id, config->mqtt_broker_address, config->mqtt_broker_port, 0, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.username = config->mqtt_username;
    conn_opts.password = config->mqtt_password;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return -1;
    }

    return 0;
}

// Function to publish a reading to MQTT
int publish_reading(const Config *config, float reading) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[50];

    snprintf(payload, sizeof(payload), "%.2f", reading);
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, config->mqtt_topic, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    MQTTClient_waitForCompletion(client, token, 1000); // Wait for 1 second

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (client) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
    }
    gpioTerminate();
}

int main() {
    // Read configuration from file
    if (read_config("config.ini", &config) != 0) {
        fprintf(stderr, "Failed to read configuration file\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, config.ads1115_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (initialize_mqtt(&config) != 0) {
        fprintf(stderr, "Failed to initialize MQTT\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int reading_count = 0;
    while (reading_count < config.readings_to_publish && !terminate) {
        // Read ADC value
        int16_t adc_value = i2cReadWordData(i2c_handle, 0x00); // Register address
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Convert ADC value to voltage (assuming +/- 4.096V range)
        float voltage = (float)adc_value * 4.096 / 32768.0;

        // Publish reading to MQTT
        if (publish_reading(&config, voltage) != 0) {
            fprintf(stderr, "Failed to publish reading\n");
            break; // Exit loop on error
        }

        printf("Published reading: %.2f V\n", voltage);
        reading_count++;

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

