#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_set_value(line, 0); // Set GPIO to LOW
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    int ret;
    struct timespec sleep_time;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line handle
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    sleep_time.tv_sec = 5;  // 5 seconds
    sleep_time.tv_nsec = 0;

    while (1) {
        // Toggle GPIO state
        int current_value = gpiod_line_get_value(line);
        int new_value = !current_value;
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, new_value);

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (in case the loop breaks due to an error)
    gpiod_line_set_value(line, 0); // Set GPIO to LOW
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

