    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d on chip %s initialized for output.  Press Ctrl+C to exit.\n", GPIO_PIN, GPIO_CHIP);

    // Main loop
    while (keep_running) {
        // Toggle the GPIO line
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        // Print the current state
        printf("GPIO %d is now %s\n", GPIO_PIN, gpiod_line_get_value(line) ? "HIGH" : "LOW");

        // Sleep for 0.1 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d on chip %s released.\n", GPIO_PIN, GPIO_CHIP);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

// Define the UART port (e.g., /dev/ttyS0 or /dev/ttyAMA0)
#define UART_PORT "/dev/ttyS0"

// Define the baud rate (e.g., 9600)
#define BAUD_RATE B9600

// Define the data buffer size
#define DATA_BUFFER_SIZE 256

// Global variables
int uart_fd = -1; // UART file descriptor
volatile sig_atomic_t terminate = 0; // Termination flag

// Structure to hold program state
typedef struct {
    int uart_fd;
    char data_buffer[DATA_BUFFER_SIZE];
    int data_buffer_index;
} ProgramState;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the UART port
int init_uart(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD; // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart(int fd, char *buffer, int buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    }
}

// Function to process the received data (print to stdout)
void process_data(const char *data) {
    printf("%s", data);
}

// Function to close the UART port
void close_uart(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the UART port
    uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    char data_buffer[DATA_BUFFER_SIZE];
    int data_buffer_index = 0;

    // Main loop
    while (!terminate) {
        int bytes_read = read_uart(uart_fd, data_buffer, DATA_BUFFER_SIZE);
        if (bytes_read > 0) {
            // Process the received data
            process_data(data_buffer);

            // Reset the buffer index
            data_buffer_index = 0;
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            sleep(1); // Wait before retrying
        }

        // Small delay to prevent busy-waiting
        usleep(10000); // 10ms
    }

    // Close the UART port
    close_uart(uart_fd);

    fprintf(stderr, "Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (set PWR_MGMT_1 to 0)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (write(fd, data, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    data[0] = ACCEL_CONFIG;
    data[1] = 0x00;
    if (write(fd, data, 2) != 2) {
        perror("Failed to write to ACCEL_CONFIG");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    uint8_t reg = ACCEL_XOUT_H;

    // Write the starting register address to the I2C device
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    // Read 6 bytes of data (X, Y, Z accelerations)
    if (read(fd, data, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    // Combine high and low bytes to form 16-bit signed integers
    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed. Check I2C connection.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer(i2c_fd, &x, &y, &z) == 0) {
            // Print the accelerometer readings
            printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data);
int bmp280_init(int fd);
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
void signal_handler(int signal);
int read_calibration_data(int fd, struct bmp280_calib_data *calib);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// BMP280 initialization function
int bmp280_init(int fd) {
    // Check the device ID
    uint8_t chip_id;
    if (i2c_read_bytes(fd, BMP280_REG_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Reset the device
    if (i2c_write_byte(fd, BMP280_REG_RESET, 0xB6) != 0) {
        fprintf(stderr, "Error resetting device\n");
        return -1;
    }
    usleep(10000); // Wait for the reset to complete

    // Configure the sensor (example configuration)
    if (i2c_write_byte(fd, BMP280_REG_CONFIG, 0x04) != 0) { // t_sb = 0.5ms
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }

    if (i2c_write_byte(fd, BMP280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Error writing control register\n");
        return -1;
    }

    // Read calibration data
    if (read_calibration_data(fd, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Read calibration data from the BMP280
int read_calibration_data(int fd, struct bmp280_calib_data *calib) {
    uint8_t data[26];
    if (i2c_read_bytes(fd, BMP280_REG_CALIB_00, data, 26) != 0) {
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    if (i2c_read_bytes(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using calibration data
double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temperature / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    printf("BMP280 sensor initialized successfully\n");

    // Main loop
    while (program_running) {
        // Read raw data
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = bmp280_compensate_temperature(raw_temperature);
            pressure = bmp280_compensate_pressure(raw_pressure, temperature);

            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Print data to standard output
            printf("%s, Temperature: %.2f °C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_GPIO 4
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 500000 // 50% duty cycle

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", result);
        return 1;
    }

    // Set GPIO 4 as an output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM duty cycle
    gpioPWM(PWM_GPIO, PWM_DUTY_CYCLE / 1000000.0); // pigpio duty cycle is 0-1

    // Print the current state
    printf("PWM GPIO %d set to %d\n", PWM_GPIO, PWM_DUTY_CYCLE);

    // Wait for a signal to terminate
    while (!terminate) {
        sleep(1);
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_1 5
#define GPIO_LINE_2 6
#define GPIO_LINE_3 13

// Define chip and line numbers
#define CHIP_NUMBER 0
#define LINE_NUMBER_1 5
#define LINE_NUMBER_2 6
#define LINE_NUMBER_3 13

// Define the number of lines
#define NUM_LINES 3

// Define the number of iterations
#define NUM_ITERATIONS 1

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_LINES];

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < NUM_LINES; i++)
    {
        if (lines[i] != NULL)
        {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the chip
    if (chip != NULL)
    {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int i;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    lines[0] = gpiod_chip_get_line(chip, GPIO_LINE_1);
    lines[1] = gpiod_chip_get_line(chip, GPIO_LINE_2);
    lines[2] = gpiod_chip_get_line(chip, GPIO_LINE_3);

    if (!lines[0] || !lines[1] || !lines[2])
    {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    // Request GPIO lines for output
    for (i = 0; i < NUM_LINES; i++)
    {
        ret = gpiod_line_request_output(lines[i], "gpio-control", 0);
        if (ret < 0)
        {
            perror("Error requesting GPIO line for output");
            goto cleanup;
        }
    }

    // Iterate through the states
    for (i = 0; i < NUM_ITERATIONS; i++)
    {
        // Set GPIO lines to HIGH
        for (int j = 0; j < NUM_LINES; j++)
        {
            ret = gpiod_line_set_value(lines[j], 1);
            if (ret < 0)
            {
                perror("Error setting GPIO line value");
                goto cleanup;
            }
        }

        // Print the state
        printf("GPIO 5, 6, 13 set to HIGH\n");

        // Wait for 1 second
        sleep(1);

        // Set GPIO lines to LOW
        for (int j = 0; j < NUM_LINES; j++)
        {
            ret = gpiod_line_set_value(lines[j], 0);
            if (ret < 0)
            {
                perror("Error setting GPIO line value");
                goto cleanup;
            }
        }

        // Print the state
        printf("GPIO 5, 6, 13 set to LOW\n");

        // Wait for 1 second
        sleep(1);
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < NUM_LINES; i++)
    {
        if (lines[i] != NULL)
        {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the chip
    if (chip != NULL)
    {
        gpiod_chip_close(chip);
    }

    return 0;
}

