static volatile int running = 1;
MQTTClient client;
Config config;

// Function prototypes
void load_config(const char *filename, Config *config);
int read_sensor(int gpio_pin);
char* get_timestamp();
int publish_message(MQTTClient client, const char *topic, const char *payload);
void signal_handler(int signal);
int mqtt_connect_with_retry(MQTTClient *client, const char *address, int port, const char *client_id, const char *username, const char *password);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Load configuration from file
void load_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        exit(EXIT_FAILURE);
    }

    // Read configuration parameters
    fscanf(fp, "mqtt_broker_address = %99s\n", config->mqtt_broker_address);
    fscanf(fp, "mqtt_broker_port = %d\n", &config->mqtt_broker_port);
    fscanf(fp, "mqtt_topic = %99s\n", config->mqtt_topic);
    fscanf(fp, "sensor_gpio_pin = %d\n", &config->sensor_gpio_pin);
    fscanf(fp, "publish_interval_seconds = %d\n", &config->publish_interval_seconds);

    fclose(fp);
}

// Read sensor value from GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Get current timestamp
char* get_timestamp() {
    struct timeval tv;
    struct tm* ptm;
    char* timestamp = malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    gettimeofday(&tv, NULL);
    ptm = localtime(&tv.tv_sec);

    strftime(timestamp, 25, "%Y-%m-%d %H:%M:%S", ptm);
    return timestamp;
}

// Publish message to MQTT broker
int publish_message(MQTTClient client, const char *topic, const char *payload) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    rc = MQTTClient_waitForCompletion(client, token, 1000); // Wait for 1 second
    MQTTClient_freeMessage(&pubmsg);
    MQTTClient_free(topic);
    return rc;
}

// MQTT connect with retry
int mqtt_connect_with_retry(MQTTClient *client, const char *address, int port, const char *client_id, const char *username, const char *password) {
    int rc = 0;
    int retry_count = 0;
    const int max_retries = 5;
    int delay = 1; // Initial delay in seconds

    while (retry_count < max_retries) {
        rc = MQTTClient_connect(*client, NULL);
        if (rc == MQTTCLIENT_SUCCESS) {
            printf("Connected to MQTT broker\n");
            return rc;
        } else {
            fprintf(stderr, "Failed to connect to MQTT broker, return code %d. Retrying in %d seconds...\n", rc, delay);
            sleep(delay);
            delay *= 2; // Exponential backoff
            retry_count++;
        }
    }

    fprintf(stderr, "Failed to connect to MQTT broker after %d retries. Exiting.\n", max_retries);
    return rc;
}

int main() {
    // Load configuration from file
    load_config("config.txt", &config);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(config.sensor_gpio_pin, PI_INPUT);

    // Initialize MQTT client
    int rc = MQTTClient_create(&client, config.mqtt_broker_address, "sensor_reader", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create client, return code %d\n", rc);
        gpioTerminate();
        return 1;
    }

    // Set MQTT connection options
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    // Connect to MQTT broker with retry
    if (mqtt_connect_with_retry(&client, config.mqtt_broker_address, config.mqtt_broker_port, "sensor_reader", NULL, NULL) != MQTTCLIENT_SUCCESS) {
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor value
        int sensor_value = read_sensor(config.sensor_gpio_pin);

        // Get timestamp
        char* timestamp = get_timestamp();

        // Format payload
        char payload[100];
        snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"sensor_value\": %d}", timestamp, sensor_value);

        // Publish message
        if (publish_message(client, config.mqtt_topic, payload) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message\n");
        }

        free(timestamp);

        // Wait for the specified interval
        sleep(config.publish_interval_seconds);
    }

    // Disconnect from MQTT broker
    MQTTClient_disconnect(client, 1000);

    // Destroy MQTT client
    MQTTClient_destroy(&client);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

