#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN_1, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_2, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_3, 1000); // 1 kHz

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(PWM_PIN_1, 1000);
    gpioSetPWMrange(PWM_PIN_2, 1000);
    gpioSetPWMrange(PWM_PIN_3, 1000);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Generate PWM signal (adjust duty cycle as needed)
        gpioPWM(PWM_PIN_1, 500); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 250); // 25% duty cycle
        gpioPWM(PWM_PIN_3, 750); // 75% duty cycle

        // Print current PWM states to standard output
        printf("PWM1: %d, PWM2: %d, PWM3: %d\n", gpioGetPWMdutycycle(PWM_PIN_1), gpioGetPWMdutycycle(PWM_PIN_2), gpioGetPWMdutycycle(PWM_PIN_3));

        // Wait for 0.05 seconds
        gpioDelay(50000); // 50 ms
    }

    // Stop PWM signal
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILE "image.jpg"

typedef struct {
    void   *start;
    size_t  length;
} buffer;

static int                  fd = -1;
static buffer              *buffers = NULL;
static unsigned int         n_buffers = 0;

static void errno_exit(const char * s)
{
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static void signal_handler(int signal)
{
    printf("Caught signal %d, exiting...\n", signal);

    if (fd != -1) {
        /* Stop streaming */
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
            fprintf(stderr, "VIDIOC_STREAMOFF failed: %d, %s\n", errno, strerror(errno));
        }

        /* Unmap buffers */
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (-1 == munmap(buffers[i].start, buffers[i].length)) {
                fprintf(stderr, "munmap failed: %d, %s\n", errno, strerror(errno));
            }
        }

        /* Free buffers */
        free(buffers);

        /* Close device */
        if (-1 == close(fd)) {
            fprintf(stderr, "close failed: %d, %s\n", errno, strerror(errno));
        }
        fd = -1;
    }

    exit(0);
}

int main()
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;
    enum v4l2_buf_type type;

    /* Install signal handler */
    signal(SIGINT, signal_handler);

    /* Open device */
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (-1 == fd) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", DEVICE_NAME, errno, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Check capabilities */
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %d, %s\n", errno, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set image format */
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %d, %s\n", errno, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Request buffers */
    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s does not support memory mapping\n", DEVICE_NAME);
            close(fd);
            return EXIT_FAILURE;
        } else {
            fprintf(stderr, "VIDIOC_REQBUFS failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    n_buffers = req.count;

    /* Map buffers */
    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            fprintf(stderr, "mmap failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
    }

    /* Queue buffers */
    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }
    }

    /* Start streaming */
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %d, %s\n", errno, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Capture loop */
    while (1) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            fprintf(stderr, "VIDIOC_DQBUF failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        // Save the captured image to a file
        FILE *fp = fopen(IMAGE_FILE, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file for writing: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
        fclose(fp);

        printf("Image saved to %s\n", IMAGE_FILE);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF failed: %d, %s\n", errno, strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        sleep(1); // Capture every 1 second
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILE "image.rgb"

struct buffer {
    void   *start;
    size_t  length;
};

static int                  fd = -1;
static struct buffer         *buffers = NULL;
static unsigned int           n_buffers = 0;

static void errno_exit(const char * s)
{
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (fd != -1) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (munmap(buffers[i].start, buffers[i].length) == -1) {
                fprintf(stderr, "munmap failed\n");
            }
        }
        free(buffers);
        close(fd);
    }
    exit(0);
}

int main(void)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;
    FILE *fp;
    time_t rawtime;
    struct tm * timeinfo;
    char filename[80];

    signal(SIGINT, signal_handler);

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", DEVICE_NAME, errno, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));

    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QUERYBUF error\n");
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL /* start anywhere */,
                                      buf.length,
                                      PROT_READ | PROT_WRITE /* required */,
                                      MAP_SHARED /* recommended */,
                                      fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "mmap failed\n");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QBUF error\n");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.rgb", timeinfo);

    fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file for writing\n");
        close(fd);
        return EXIT_FAILURE;
    }

    fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
    fclose(fp);

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMOFF error\n");
        close(fd);
        return EXIT_FAILURE;
    }

    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            fprintf(stderr, "munmap failed\n");
        }
    }

    free(buffers);
    close(fd);

    printf("Image saved to %s\n", filename);

    return EXIT_SUCCESS;
}

