#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

// Define the UART port (e.g., /dev/ttyS0 or /dev/ttyAMA0)
#define UART_PORT "/dev/ttyS0"

// Define the baud rate (e.g., 9600, 115200)
#define BAUD_RATE B9600

// Define the data format (e.g., "R,X,Y,Z\n")
#define DATA_FORMAT "R,%d,%d,%d\n"

// Define the maximum data length
#define MAX_DATA_LENGTH 256

// Global variable for the UART file descriptor
int uart_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (uart_fd != -1) {
        close(uart_fd);
    }
    exit(0);
}

// Function to initialize the UART port
int init_uart(const char *port, speed_t baud_rate)
{
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart_data(int fd, char *buffer, size_t buffer_size)
{
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    }
}

// Function to parse the data and extract the values
int parse_data(const char *data, int *x, int *y, int *z)
{
    char *token;
    char *rest = (char *)data; // Cast away const for strtok

    // Get the first token (R)
    token = strtok_r(rest, ",", &rest);
    if (token == NULL || strcmp(token, "R") != 0) {
        fprintf(stderr, "Error: Invalid data format (missing R)\n");
        return -1;
    }

    // Get the X value
    token = strtok_r(rest, ",", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid data format (missing X)\n");
        return -1;
    }
    *x = atoi(token);

    // Get the Y value
    token = strtok_r(rest, ",", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid data format (missing Y)\n");
        return -1;
    }
    *y = atoi(token);

    // Get the Z value
    token = strtok_r(rest, "\n", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid data format (missing Z)\n");
        return -1;
    }
    *z = atoi(token);

    return 0;
}

// Function to print the data to standard output
void print_data(int x, int y, int z)
{
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
}

int main()
{
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the UART port
    uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        return 1;
    }

    char data_buffer[MAX_DATA_LENGTH];
    int x, y, z;

    // Main loop to read and process data
    while (1) {
        // Read data from the UART port
        int bytes_read = read_uart_data(uart_fd, data_buffer, MAX_DATA_LENGTH);
        if (bytes_read > 0) {
            // Parse the data
            if (parse_data(data_buffer, &x, &y, &z) == 0) {
                // Print the data
                print_data(x, y, z);
            } else {
                fprintf(stderr, "Error parsing data: %s", data_buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading data. Retrying...");
            sleep(1); // Wait before retrying
        }

        usleep(100000); // Sleep for 100ms to avoid busy-waiting
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    close(uart_fd);
    return 0;
}

