#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Main loop to control PWM outputs
    while (program_running) {
        // Set PWM duty cycle for PWM_PIN_1
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle (0-255 range)
        printf("PWM_PIN_1: 128\n");

        // Set PWM duty cycle for PWM_PIN_2
        gpioPWM(PWM_PIN_2, 64);  // 25% duty cycle
        printf("PWM_PIN_2: 64\n");

        // Set PWM duty cycle for PWM_PIN_3
        gpioPWM(PWM_PIN_3, 0);   // 0% duty cycle
        printf("PWM_PIN_3: 0\n");

        // Wait for 0.5 seconds
        time_sleep(0.5);
    }

    // Stop PWM on all pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Define the GPIO pin number (BCM numbering)
#define DHT22_GPIO 4

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO line and chip
struct gpiod_chip *chip;
struct gpiod_line *line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to read data from DHT22 sensor
int read_dht22(float *temperature, float *humidity)
{
    int i;
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        perror("Failed to request GPIO line for output");
        return -1;
    }

    // Send start signal
    gpiod_line_set_value(line, 0);
    usleep(1000); // 1ms
    gpiod_line_set_value(line, 1);
    usleep(30); // 30us

    // Set the GPIO line for input
    if (gpiod_line_request_input(line, "dht22") < 0) {
        perror("Failed to request GPIO line for input");
        return -1;
    }

    // Read the data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go high
        int count = 0;
        while (gpiod_line_get_value(line) == 0) {
            usleep(1); // Wait 1 us
            count++;
            if (count > 100) {
                fprintf(stderr, "Timeout waiting for line to go high\n");
                return -1;
            }
        }

        // Measure the length of the high pulse
        count = 0;
        while (gpiod_line_get_value(line) == 1) {
            usleep(1); // Wait 1 us
            count++;
            if (count > 100) {
                fprintf(stderr, "Timeout waiting for line to go low\n");
                return -1;
            }
        }

        // Determine if it's a 0 or a 1 based on the pulse length
        if (count > 40) {
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    // Calculate temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

int main()
{
    float temperature, humidity;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, DHT22_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Read the DHT22 sensor
    ret = read_dht22(&temperature, &humidity);

    if (ret == 0) {
        // Print the temperature and humidity
        printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT22 sensor\n");
    }

    // Release the GPIO line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return ret;
}

