    }
    if (line23) {
        gpiod_line_release(line23);
    }
    if (line24) {
        gpiod_line_release(line24);
    }
    if (line25) {
        gpiod_line_release(line25);
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for each pin
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    line25 = gpiod_chip_get_line(chip, GPIO_25);

    if (!line17 || !line23 || !line24 || !line25) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line17, "gpio-control", 0) < 0 ||
        gpiod_line_request_output(line23, "gpio-control", 0) < 0 ||
        gpiod_line_request_output(line24, "gpio-control", 0) < 0 ||
