        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_line_release(line24);
        gpiod_line_release(line25);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 17
        int value = gpiod_line_get_value(line17);
        gpiod_line_set_value(line17, !value);
        printf("GPIO %d: %d\n", GPIO_17, !value);

        // Toggle GPIO 23
        value = gpiod_line_get_value(line23);
        gpiod_line_set_value(line23, !value);
        printf("GPIO %d: %d\n", GPIO_23, !value);

        // Toggle GPIO 24
        value = gpiod_line_get_value(line24);
        gpiod_line_set_value(line24, !value);
        printf("GPIO %d: %d\n", GPIO_24, !value);

        // Toggle GPIO 25
