#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <MQTTClient.h>

// Configuration structure
typedef struct {
    char mqtt_broker_address[100];
    int mqtt_broker_port;
    char mqtt_client_id[50];
    char mqtt_topic[100];
    int spi_channel;
    int sensor_channels[4];
    int num_sensors;
} Config;

// Global variables
static volatile int running = 1;
static Config config;
static MQTTClient client;

// Function prototypes
int read_config(const char *filename, Config *config);
int read_mcp3008(int channel);
int publish_sensor_data(MQTTClient client, const char *topic, int sensor_id, int reading);
void signal_handler(int signal);
int mqtt_connect_with_retry(MQTTClient *client, const char *address, int port, const char *client_id);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "mqtt_broker_address") == 0) {
            strncpy(config->mqtt_broker_address, value, sizeof(config->mqtt_broker_address) - 1);
            config->mqtt_broker_address[sizeof(config->mqtt_broker_address) - 1] = '\0';
        } else if (strcmp(key, "mqtt_broker_port") == 0) {
            config->mqtt_broker_port = atoi(value);
        } else if (strcmp(key, "mqtt_client_id") == 0) {
            strncpy(config->mqtt_client_id, value, sizeof(config->mqtt_client_id) - 1);
            config->mqtt_client_id[sizeof(config->mqtt_client_id) - 1] = '\0';
        } else if (strcmp(key, "mqtt_topic") == 0) {
            strncpy(config->mqtt_topic, value, sizeof(config->mqtt_topic) - 1);
            config->mqtt_topic[sizeof(config->mqtt_topic) - 1] = '\0';
        } else if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strncmp(key, "sensor_channel_", 15) == 0) {
            int sensor_id = atoi(key + 15);
            if (sensor_id >= 0 && sensor_id < 4) {
                config->sensor_channels[sensor_id] = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    int handle = spiOpen(config.spi_channel, 100000, 0); // Open SPI channel
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(handle, tx_buffer, rx_buffer, 3); // Transfer data

    spiClose(handle); // Close SPI channel

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to publish sensor data to MQTT broker
int publish_sensor_data(MQTTClient client, const char *topic, int sensor_id, int reading) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"sensor_id\": %d, \"reading\": %d}", sensor_id, reading);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }

    rc = MQTTClient_waitForCompletion(client, token, 1000); // Wait for 1 second
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Timeout waiting for publication: %s\n", MQTTClient_strerror(rc));
        return -1;
    }

    return 0;
}

// Function to connect to MQTT broker with retry
int mqtt_connect_with_retry(MQTTClient *client, const char *address, int port, const char *client_id) {
    int rc;
    int retry_count = 0;
    const int max_retries = 5;
    int delay = 1; // Initial delay in seconds

    while (retry_count < max_retries) {
        MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
        conn_opts.keepAliveInterval = 20;
        conn_opts.cleansession = 1;
        conn_opts.clientID = client_id;

        rc = MQTTClient_connect(*client, &conn_opts);
        if (rc == MQTTCLIENT_SUCCESS) {
            printf("Connected to MQTT broker at %s:%d\n", address, port);
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to connect to MQTT broker: %s, retrying in %d seconds...\n", MQTTClient_strerror(rc), delay);
            sleep(delay);
            delay *= 2; // Exponential backoff
            retry_count++;
        }
    }

    fprintf(stderr, "Failed to connect to MQTT broker after %d retries.\n", max_retries);
    return -1; // Failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Read configuration from file
    if (read_config("config.txt", &config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT client
    int rc = MQTTClient_create(&client, config.mqtt_broker_address, config.mqtt_client_id, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker with retry
    if (mqtt_connect_with_retry(&client, config.mqtt_broker_address, config.mqtt_broker_port, config.mqtt_client_id) != 0) {
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        for (int i = 0; i < config.num_sensors; i++) {
            int reading = read_mcp3008(config.sensor_channels[i]);
            if (reading != -1) {
                if (publish_sensor_data(client, config.mqtt_topic, i, reading) != 0) {
                    fprintf(stderr, "Failed to publish data for sensor %d\n", i);
                }
            } else {
                fprintf(stderr, "Failed to read sensor %d\n", i);
            }
        }

        sleep(1); // Publish data every 1 second
    }

    // Disconnect from MQTT broker
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILE "image.jpg"

// Structure to hold device information
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
} device_info_t;

// Function to initialize the device
int initialize_device(device_info_t *dev) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    dev->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (dev->fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(dev->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(dev->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        close(dev->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming\n");
        close(dev->fd);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(dev->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(dev->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(dev->fd);
        return -1;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(dev->fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(dev->fd);
        return -1;
    }

    dev->buffer_size = buf.length;
    dev->buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, dev->fd, buf.m.offset);
    if (dev->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(dev->fd);
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(device_info_t *dev) {
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers req;

    // Queue the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(dev->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(dev->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    // Dequeue the buffer
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(dev->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(dev->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Error: Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(dev->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Save the image to a file
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    fwrite(dev->buffer, 1, buf.bytesused, fp);
    fclose(fp);

    // Stop streaming
    if (ioctl(dev->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to clean up resources
void cleanup_device(device_info_t *dev) {
    if (dev->buffer != NULL && dev->buffer != MAP_FAILED) {
        if (munmap(dev->buffer, dev->buffer_size) < 0) {
            perror("Error unmapping buffer");
        }
    }
    if (dev->fd > 0) {
        close(dev->fd);
    }
}

int main() {
    device_info_t dev;
    dev.fd = -1;
    dev.buffer = NULL;
    dev.buffer_size = 0;

    if (initialize_device(&dev) != 0) {
        fprintf(stderr, "Failed to initialize device. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (capture_image(&dev) != 0) {
        fprintf(stderr, "Failed to capture image. Exiting.\n");
        cleanup_device(&dev);
        return EXIT_FAILURE;
    }

    printf("Image captured and saved to %s\n", IMAGE_FILE);

    cleanup_device(&dev);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN_1, 0); // Stop PWM on pin 4
    gpioPWM(PWM_PIN_2, 0); // Stop PWM on pin 5
    gpioPWM(PWM_PIN_3, 0); // Stop PWM on pin 6
    gpioPWM(PWM_PIN_4, 0); // Stop PWM on pin 7
    gpioPWM(PWM_PIN_5, 0); // Stop PWM on pin 8
    gpioPWM(PWM_PIN_6, 0); // Stop PWM on pin 9
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN_1, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
