    gpiod_line_set_value(line, 0); // Set GPIO to LOW
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x20

// Define the GPIO pins for the PCF8574
#define PCF8574_PIN_A 0x01
#define PCF8574_PIN_B 0x02
#define PCF8574_PIN_C 0x04
#define PCF8574_PIN_D 0x08

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a value to the PCF8574
int write_pcf8574(int fd, uint8_t value) {
    if (write(fd, &value, 1) != 1) {
        perror("Error writing to PCF8574");
        return -1;
    }
    return 0;
}

// Function to display a value on the PCF8574
int display_value(int fd, int value) {
    uint8_t pcf8574_value = 0;

    // Clear all pins
    pcf8574_value = 0x00;

    // Set the appropriate pins based on the value
    if (value & 0x01) pcf8574_value |= PCF8574_PIN_A;
    if (value & 0x02) pcf8574_value |= PCF8574_PIN_B;
    if (value & 0x04) pcf8574_value |= PCF8574_PIN_C;
    if (value & 0x08) pcf8574_value |= PCF8574_PIN_D;

    if (write_pcf8574(fd, pcf8574_value) != 0) {
        return -1;
    }

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, PCF8574_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    printf("PCF8574 display program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Generate a random value between 0 and 15
        int value = rand() % 16;

        // Display the value on the PCF8574
        if (display_value(i2c_fd, value) != 0) {
            fprintf(stderr, "Error displaying value. Exiting.\n");
            break;
        }

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup (should not reach here if signal handler works)
    close(i2c_fd);
    return 0;
}

