    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line1, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 1 for output");
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial state to LOW
    ret = gpiod_line_set_value(line1, 0);
    if (ret < 0) {
        perror("Error setting GPIO line 1 to LOW");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_set_value(line2, 0);
    if (ret < 0) {
        perror("Error setting GPIO line 2 to LOW");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print initial state
    printf("GPIO %d (BCM %d) set to LOW\n", GPIO_PIN_1, GPIO_PIN_1);
    printf("GPIO %d (BCM %d) set to LOW\n", GPIO_PIN_2, GPIO_PIN_2);

    // Set delay for 1 second
    delay.tv_sec = 1;
    delay.tv_nsec = 0;

    // Sleep for 1 second
    nanosleep(&delay, NULL);

    // Set GPIO lines to HIGH
    ret = gpiod_line_set_value(line1, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 1 to HIGH");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_set_value(line2, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 2 to HIGH");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print new state
    printf("GPIO %d (BCM %d) set to HIGH\n", GPIO_PIN_1, GPIO_PIN_1);
    printf("GPIO %d (BCM %d) set to HIGH\n", GPIO_PIN_2, GPIO_PIN_2);

    // Clean up and exit
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

