    keep_running = 0;
    printf("\nCaught signal, exiting...\n");
}

int main()
{
    int ret;
    int i;
    struct timespec sleep_time = {0, 10000000}; // 0.01 seconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
