#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout in microseconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Exiting gracefully...\n");
}

// Function to trigger the HC-SR04
void trigger_hc_sr04() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance in centimeters
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    trigger_hc_sr04();

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse not received (start).\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse not received (end).\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate the pulse duration in microseconds
    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN_1, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);
    gpioSetPWMrange(PWM_PIN_4, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        // Generate PWM signal (adjust duty cycle as needed)
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 64);  // 25% duty cycle
        gpioPWM(PWM_PIN_3, 192); // 75% duty cycle
        gpioPWM(PWM_PIN_4, 0);   // 0% duty cycle

        // Print current PWM states
        printf("PWM1: %d, PWM2: %d, PWM3: %d, PWM4: %d\n",
               gpioGetPWMdutycycle(PWM_PIN_1),
               gpioGetPWMdutycycle(PWM_PIN_2),
               gpioGetPWMdutycycle(PWM_PIN_3),
               gpioGetPWMdutycycle(PWM_PIN_4));

        // Wait for 1 second
        sleep(1);
    }

    // Stop PWM signal
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILENAME "image.jpg"

typedef struct {
    void   *start;
    size_t  length;
} buffer;

static int                  fd = -1;
static buffer              *buffers = NULL;
static unsigned int         n_buffers = 0;
static struct v4l2_capability cap;
static struct v4l2_format   fmt;

void cleanup(int signal);
int xioctl(int fd, int request, void *arg);
int init_device(void);
int init_mmap(void);
int start_capturing(void);
int stop_capturing(void);
int uninit_device(void);
int write_image_to_file(const void *buffer, size_t size);

void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");
    if (fd != -1) {
        stop_capturing();
        uninit_device();
        close(fd);
    }
    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }
    exit(0);
}

int xioctl(int fd, int request, void *arg) {
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    if (-1 == r) {
        perror("ioctl");
        return -1;
    }
    return 0;
}

int init_device(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "VIDIOC_QUERYCAP error\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Not a video capture device\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Does not support streaming i/o\n");
        return -1;
    }

    /* Select video input, if you have more than one */
    // struct v4l2_input input;
    // input.index = 0;
    // xioctl(fd, VIDIOC_ENUMINPUT, &input);
    // printf("Video input: %s\n", input.name);

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG; // Request JPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT error\n");
        return -1;
    }

    return 0;
}

int init_mmap(void) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));

    req.count = 1; // Single buffer for simplicity
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "Memory mapping not supported\n");
        } else {
            fprintf(stderr, "VIDIOC_REQBUFS error\n");
        }
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF error\n");
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "mmap error\n");
            return -1;
        }
    }

    return 0;
}

int start_capturing(void) {
    unsigned int i;
    enum v4l2_buf_type type;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF error\n");
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON error\n");
        return -1;
    }

    return 0;
}

int stop_capturing(void) {
    enum v4l2_buf_type type;

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        fprintf(stderr, "VIDIOC_STREAMOFF error\n");
        return -1;
    }

    return 0;
}

int uninit_device(void) {
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            fprintf(stderr, "munmap error\n");
            return -1;
        }
    }

    free(buffers);
    return 0;
}

int write_image_to_file(const void *buffer, size_t size) {
    FILE *fp = fopen(IMAGE_FILENAME, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file for writing\n");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, size, fp);
    if (bytes_written != size) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Image saved to %s\n", IMAGE_FILENAME);
    return 0;
}

int main(void) {
    struct v4l2_buffer buf;
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);

    if (-1 == fd) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", DEVICE_NAME, errno, strerror(errno));
        return EXIT_FAILURE;
    }

    if (-1 == init_device()) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (-1 == init_mmap()) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (-1 == start_capturing()) {
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            fprintf(stderr, "select error\n");
            break;
        }

        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            fprintf(stderr, "VIDIOC_DQBUF error\n");
            break;
        }

        if (write_image_to_file(buffers[0].start, buf.bytesused) == 0) {
            // Successfully wrote image to file
        } else {
            fprintf(stderr, "Failed to write image to file\n");
        }

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF error\n");
            break;
        }

        usleep(100000); // 0.1 seconds
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

