#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x20
#define MAX_RETRIES 3

// Function to write data to the PCF8574
int write_pcf8574(int fd, unsigned char data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = write(fd, &data, 1);
        if (result == 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to PCF8574: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to write to PCF8574 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

int main() {
