    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get current time
    time(&rawtime);
