#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = read_register(fd, ACCEL_XOUT_H);
    x_l = read_register(fd, ACCEL_XOUT_H + 1);
    y_h = read_register(fd, ACCEL_YOUT_H);
    y_l = read_register(fd, ACCEL_YOUT_H + 1);
    z_h = read_register(fd, ACCEL_ZOUT_H);
    z_l = read_register(fd, ACCEL_ZOUT_H + 1);

    if (x_h < 0 || x_l < 0 || y_h < 0 || y_l < 0 || z_h < 0 || z_l < 0) {
        return -1; // Indicate error
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0; // Indicate success
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep bit)
    if (write_register(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Configure accelerometer range (+/- 2g)
    if (write_register(i2c_fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring accelerometer range\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;

        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            printf("Accelerometer Data: X=%6d, Y=%6d, Z=%6d\n", x, y, z);
        } else {
            fprintf(stderr, "Error reading accelerometer data\n");
        }

        usleep(100000); // 0.1 seconds
    }

    // The program should never reach here due to the infinite loop,
    // but include close(i2c_fd) and exit(0) for completeness.
    close(i2c_fd);
    exit(0);
}

