    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO lines
    gpio_line_1 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_1);
    gpio_line_2 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_2);
    gpio_line_3 = gpiod_chip_get_line(gpio_chip, GPIO_PIN_3);

    if (!gpio_line_1 || !gpio_line_2 || !gpio_line_3) {
        fprintf(stderr, "Error: Could not get GPIO line\n");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio_line_1, "gpio-control", 0) < 0 ||
        gpiod_line_request_output(gpio_line_2, "gpio-control", 0) < 0 ||
        gpiod_line_request_output(gpio_line_3, "gpio-control", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for output\n");
        gpiod_line_release(gpio_line_1);
        gpiod_line_release(gpio_line_2);
        gpiod_line_release(gpio_line_3);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3 && !terminate; ++i) {
        // Read data from I2C
        int i2c_data = read_i2c_data(i2c_fd, I2C_ADDRESS, I2C_REGISTER);
        if (i2c_data < 0) {
            fprintf(stderr, "Error: Could not read I2C data\n");
            continue; // Skip to the next iteration
        }

        // Validate I2C data
        if (!validate_i2c_data(i2c_data)) {
            fprintf(stderr, "Error: Invalid I2C data received\n");
            continue; // Skip to the next iteration
        }

        // Set GPIO outputs
        if (set_gpio_output(gpio_line_1, (i2c_data & 0x01) ? 1 : 0) < 0 ||
            set_gpio_output(gpio_line_2, (i2c_data & 0x02) ? 1 : 0) < 0 ||
            set_gpio_output(gpio_line_3, (i2c_data & 0x04) ? 1 : 0) < 0) {
            fprintf(stderr, "Error: Could not set GPIO output\n");
            continue; // Skip to the next iteration
        }

        // Print GPIO states
        printf("GPIO 2: %d, GPIO 3: %d, GPIO 17: %d\n",
               gpiod_line_get_value(gpio_line_1),
               gpiod_line_get_value(gpio_line_2),
               gpiod_line_get_value(gpio_line_3));

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    gpiod_line_release(gpio_line_1);
    gpiod_line_release(gpio_line_2);
    gpiod_line_release(gpio_line_3);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

