#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SHT31 I2C address
#define SHT31_ADDR 0x44

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Measurement command (High Repeatability, Clock Stretching disabled)
#define MEASURE_CMD 0x2C06

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature and humidity from SHT31
int read_sht31(int fd, float *temperature, float *humidity) {
    uint8_t write_data[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t read_data[6];

    // Send measurement command
    if (write(fd, write_data, 2) != 2) {
        perror("Failed to write measurement command");
        return -1;
    }

    // Wait for measurement (typical conversion time is 10ms, but we wait 20ms to be safe)
    usleep(20000); // 20ms

    // Read 6 bytes of data (Temp MSB, Temp LSB, Temp CRC, Hum MSB, Hum LSB, Hum CRC)
    if (read(fd, read_data, 6) != 6) {
        perror("Failed to read data");
        return -1;
    }

    // Convert data
    int temp_raw = (read_data[0] << 8) | read_data[1];
    int hum_raw = (read_data[3] << 8) | read_data[4];

    // Calculate temperature (Celsius)
    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);

    // Calculate humidity (%RH)
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (1) {
        // Read SHT31 data
        if (read_sht31(i2c_fd, &temperature, &humidity) == 0) {
            // Validate data
            if (temperature >= -40.0 && temperature <= 125.0 && humidity >= 0.0 && humidity <= 100.0) {
                // Print temperature and humidity
                printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n", temperature, humidity);
            } else {
                fprintf(stderr, "Invalid sensor data: Temperature=%.2f, Humidity=%.2f\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Failed to read SHT31 data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

