#include <time.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 17

// Define number of cycles
#define NUM_CYCLES 3

// Define sleep duration (in milliseconds)
#define SLEEP_DURATION 500

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line1, *line2, *line3;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line handles
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!line1 || !line2 || !line3) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line1, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line 1 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line2, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line3, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO pins to HIGH
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("Error setting GPIO line 1 value");
            signal_handler(SIGINT);
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("Error setting GPIO line 2 value");
            signal_handler(SIGINT);
        }
        if (gpiod_line_set_value(line3, 1) < 0) {
            perror("Error setting GPIO line 3 value");
            signal_handler(SIGINT);
        }

        // Print current state
        printf("Cycle %d: GPIO 2=HIGH, GPIO 3=HIGH, GPIO 17=HIGH\n", i + 1);

        // Sleep for a short duration
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SLEEP_DURATION * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO pins to LOW
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("Error setting GPIO line 1 value");
            signal_handler(SIGINT);
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("Error setting GPIO line 2 value");
            signal_handler(SIGINT);
        }
        if (gpiod_line_set_value(line3, 0) < 0) {
            perror("Error setting GPIO line 3 value");
            signal_handler(SIGINT);
        }

        // Print current state
        printf("Cycle %d: GPIO 2=LOW, GPIO 3=LOW, GPIO 17=LOW\n", i + 1);

        // Sleep for a short duration
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    signal_handler(SIGINT);

    return 0;
}

