#define GPIO_LINE 27 // Physical pin number

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

int main()
{
    int ret;
    struct timespec delay;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial state to LOW
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Error setting initial GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set delay for 1 second
    delay.tv_sec = 1;
    delay.tv_nsec = 0;

    // Toggle the GPIO line every second
    while (keep_running) {
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            perror("Error getting GPIO line value");
            break;
        }

        int new_value = !current_value;
