        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, new_value);
        nanosleep(&delay, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   18
#define GREEN_PIN 23
#define BLUE_PIN  24

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define delay between cycles (seconds)
#define DELAY_SECONDS 0.005

// Global flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the color of the RGB LED
void set_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range for all pins
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to cycle through colors
    int cycle = 0;
    while (!terminate)
    {
        // Cycle 1: Red
        if (cycle == 0)
        {
            set_color(PWM_RANGE, 0, 0);
        }
        // Cycle 2: Green
        else if (cycle == 1)
        {
            set_color(0, PWM_RANGE, 0);
        }
        // Cycle 3: Blue
        else if (cycle == 2)
        {
            set_color(0, 0, PWM_RANGE);
        }

        // Delay for DELAY_SECONDS seconds
        gpioDelay(DELAY_SECONDS * 1000000); // Convert seconds to microseconds

        // Increment cycle counter
        cycle = (cycle + 1) % 3;
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    return 0;
}

