#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define MAX_SENSORS 10
#define MAX_SENSOR_ID_LENGTH 20
#define MAX_FILE_PATH_LENGTH 100

// Structure to hold sensor information
typedef struct {
    char id[MAX_SENSOR_ID_LENGTH];
    char file_path[MAX_FILE_PATH_LENGTH];
} sensor_t;

// Global array to store sensor information
sensor_t sensors[MAX_SENSORS];
int num_sensors = 0;

// Function prototypes
int discover_sensors();
float read_temperature(const char *sensor_id);
void signal_handler(int signum);

// Signal handler for graceful exit
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nExiting gracefully...\n");
        exit(0);
    }
}

// Function to discover DS18B20 sensors
int discover_sensors() {
    DIR *dir;
    struct dirent *ent;
    int sensor_count = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Error opening " W1_DEVICES_DIR);
        return -1;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            if (sensor_count < MAX_SENSORS) {
                strncpy(sensors[sensor_count].id, ent->d_name, MAX_SENSOR_ID_LENGTH - 1);
                sensors[sensor_count].id[MAX_SENSOR_ID_LENGTH - 1] = '\0'; // Ensure null termination
                snprintf(sensors[sensor_count].file_path, MAX_FILE_PATH_LENGTH, "%s/%s/w1_slave", W1_DEVICES_DIR, ent->d_name);
                sensor_count++;
            } else {
                fprintf(stderr, "Warning: Too many sensors found.  Ignoring %s\n", ent->d_name);
            }
        }
    }

    closedir(dir);
    num_sensors = sensor_count;
    return 0;
}

// Function to read temperature from a DS18B20 sensor
float read_temperature(const char *sensor_id) {
    char file_path[MAX_FILE_PATH_LENGTH];
    snprintf(file_path, MAX_FILE_PATH_LENGTH, "%s/%s/w1_slave", W1_DEVICES_DIR, sensor_id);

    FILE *fp = fopen(file_path, "r");
    if (fp == NULL) {
        perror("Error opening w1_slave file");
        return -1000.0; // Indicate error
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fclose(fp);
        return -1000.0; // Indicate error
    }

    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1000.0; // Indicate error
    }

    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in sensor %s\n", sensor_id);
        return -1000.0; // Indicate error
    }

    long temperature_raw = strtol(temp_str + 2, NULL, 10);
    return (float)temperature_raw / 1000.0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Discover sensors
    if (discover_sensors() != 0) {
        fprintf(stderr, "Error discovering sensors. Exiting.\n");
        return 1;
    }

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        return 1;
    }

    // Main loop
    for (int i = 0; i < num_sensors; i++) {
        float temperature = read_temperature(sensors[i].id);

        if (temperature > -999.0) {
            printf("Sensor %s: %.2f °C\n", sensors[i].id, temperature);
        } else {
            fprintf(stderr, "Error reading temperature from sensor %s\n", sensors[i].id);
        }

        sleep(5);
    }

    return 0;
}

