        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_LINE, strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    for (i = 0; i < 3 && !stop; i++) {
        // Toggle the GPIO line
        value = !gpiod_line_get_value(line);
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_LINE, strerror(-ret));
            break;
        }

        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_PIN, value);
        sleep(1);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

