#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 4
#define PWM_PIN2 17
#define PWM_PIN3 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(PWM_PIN2, PI_OUTPUT);
    gpioSetMode(PWM_PIN3, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN, 1000);
    gpioSetPWMfrequency(PWM_PIN2, 1000);
    gpioSetPWMfrequency(PWM_PIN3, 1000);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(PWM_PIN, 1000);
    gpioSetPWMrange(PWM_PIN2, 1000);
    gpioSetPWMrange(PWM_PIN3, 1000);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Read PWM duty cycle from standard input
        int duty_cycle;
        if (scanf("%d", &duty_cycle) != 1)
        {
            fprintf(stderr, "Invalid input. Please enter an integer between 0 and 1000.\n");
            // Consume any remaining input in the buffer
            while (getchar() != '\n');
            gpioDelay(100); // Small delay to prevent busy-waiting
            continue;
        }

        // Validate input
        if (duty_cycle < 0 || duty_cycle > 1000)
        {
            fprintf(stderr, "Invalid duty cycle. Please enter an integer between 0 and 1000.\n");
            gpioDelay(100); // Small delay to prevent busy-waiting
            continue;
        }

        // Set PWM duty cycle on all three pins
        gpioPWM(PWM_PIN, duty_cycle);
        gpioPWM(PWM_PIN2, duty_cycle);
        gpioPWM(PWM_PIN3, duty_cycle);

        // Print current state to standard output
        printf("PWM: %d\n", duty_cycle);

        // Delay for 0.1 seconds
        gpioDelay(100000); // 100 ms
    }

    // Clean up and exit
    gpioPWM(PWM_PIN, 0);
    gpioPWM(PWM_PIN2, 0);
    gpioPWM(PWM_PIN3, 0);
    gpioTerminate();

    return 0;
}

