#include <time.h>
#include <signal.h>
#include <errno.h>

// Define the GPIO pin number (BCM numbering)
#define DHT22_GPIO 4

// Define the number of cycles to run
#define NUM_CYCLES 3

// Define the timeout for reading the DHT22 (in milliseconds)
#define DHT22_TIMEOUT 100

// Global variables for GPIO chip and line
struct gpiod_chip *chip;
struct gpiod_line *line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to read data from the DHT22 sensor
int read_dht22(float *temperature, float *humidity)
{
    int i;
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    struct timespec start, end;
    long long elapsed_time;

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        perror("Failed to request GPIO line for output");
        return -1;
    }

    // Send the start signal
    gpiod_line_set_value(line, 0);
    usleep(1); // 1 microsecond
    gpiod_line_set_value(line, 1);
    usleep(30); // 30 microseconds

    // Request the GPIO line for input
    if (gpiod_line_request_input(line, "dht22") < 0) {
        perror("Failed to request GPIO line for input");
        gpiod_line_release(line);
        return -1;
    }

    // Read the 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go high
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_time = (end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000LL;
            if (elapsed_time > DHT22_TIMEOUT * 1000LL) {
                fprintf(stderr, "Timeout waiting for line to go high\n");
                gpiod_line_release(line);
                return -1;
            }
        }

        // Wait for the line to go low
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_time = (end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000LL;
            if (elapsed_time > DHT22_TIMEOUT * 1000LL) {
                fprintf(stderr, "Timeout waiting for line to go low\n");
                gpiod_line_release(line);
                return -1;
            }
        }

        // Measure the length of the high pulse to determine the bit value
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_time = (end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000LL;
            if (elapsed_time > DHT22_TIMEOUT * 1000LL) {
                fprintf(stderr, "Timeout waiting for line to go high again\n");
                gpiod_line_release(line);
                return -1;
            }
        }
        elapsed_time = (end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000LL;

        // Determine if the bit is a 0 or a 1 based on the pulse length
        if (elapsed_time > 40) {
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Verify the checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        gpiod_line_release(line);
        return -1;
    }

    // Calculate the temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    // Release the GPIO line
    gpiod_line_release(line);

    return 0;
}

int main()
{
    int i;
    float temperature, humidity;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, DHT22_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to read the DHT22 sensor multiple times
    for (i = 0; i < NUM_CYCLES; i++) {
        // Read the DHT22 sensor
        if (read_dht22(&temperature, &humidity) == 0) {
            // Print the temperature and humidity
            printf("Cycle %d: Temperature = %.1f°C, Humidity = %.1f%%\n", i + 1, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor in cycle %d\n", i + 1);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and exit
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

