#define PWM_PIN_2 27

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PWM_PIN_1, 0); // Stop PWM on pin 17
    gpioPWM(PWM_PIN_2, 0); // Stop PWM on pin 27
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

