    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN_1, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_2, 1000); // 1 kHz

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(PWM_PIN_1, 1000);
    gpioSetPWMrange(PWM_PIN_2, 1000);

    // Set PWM duty cycle (adjust as needed)
    gpioPWM(PWM_PIN_1, 500); // 50% duty cycle
    gpioPWM(PWM_PIN_2, 750); // 75% duty cycle

    // Print PWM states to standard output
    printf("PWM on GPIO %d: %d\n", PWM_PIN_1, gpioGetPWMdutycycle(PWM_PIN_1));
    printf("PWM on GPIO %d: %d\n", PWM_PIN_2, gpioGetPWMdutycycle(PWM_PIN_2));

