#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_23 23

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);

    // Main loop to control the GPIO pins
    while (!terminate)
    {
        // Toggle the state of GPIO 17
        gpioWrite(GPIO_17, !gpioRead(GPIO_17));

        // Toggle the state of GPIO 18
        gpioWrite(GPIO_18, !gpioRead(GPIO_18));

        // Toggle the state of GPIO 23
        gpioWrite(GPIO_23, !gpioRead(GPIO_23));

        // Report the current states to standard output
        printf("GPIO 17: %d, GPIO 18: %d, GPIO 23: %d\n",
               gpioRead(GPIO_17), gpioRead(GPIO_18), gpioRead(GPIO_23));

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0; // Exit successfully
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 4
#define PWM_PIN2 17
#define PWM_PIN3 18
#define PWM_PIN4 27

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(PWM_PIN2, PI_OUTPUT);
    gpioSetMode(PWM_PIN3, PI_OUTPUT);
    gpioSetMode(PWM_PIN4, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN, 1000);
    gpioSetPWMfrequency(PWM_PIN2, 1000);
    gpioSetPWMfrequency(PWM_PIN3, 1000);
    gpioSetPWMfrequency(PWM_PIN4, 1000);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(PWM_PIN, 1000);
    gpioSetPWMrange(PWM_PIN2, 1000);
    gpioSetPWMrange(PWM_PIN3, 1000);
    gpioSetPWMrange(PWM_PIN4, 1000);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    int duty_cycle = 0;
    int direction = 1; // 1 for increasing, -1 for decreasing
    int cycles = 0;

    while (program_running && cycles < 5) {
        // Set PWM duty cycle
        gpioPWM(PWM_PIN, duty_cycle);
        gpioPWM(PWM_PIN2, duty_cycle);
        gpioPWM(PWM_PIN3, duty_cycle);
        gpioPWM(PWM_PIN4, duty_cycle);

        // Print current state
        printf("Cycle %d, Duty Cycle: %d\n", cycles + 1, duty_cycle);

        // Update duty cycle and direction
        duty_cycle += direction;
        if (duty_cycle >= 1000) {
            duty_cycle = 1000;
            direction = -1;
        } else if (duty_cycle <= 0) {
            duty_cycle = 0;
            direction = 1;
            cycles++;
        }

        // Wait for 60 seconds
        sleep(60);
