#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for DHT22 sensors
#define DHT22_GPIO_1 4
#define DHT22_GPIO_2 17

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to read DHT22 sensor data
DHT22Data read_dht22(int gpio_pin) {
    DHT22Data data = {0.0, 0.0, 0};
    int i;
    int data_bits[40] = {0};
    unsigned int pulse_lengths[80];
    int pulse_count = 0;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1);
    gpioWrite(gpio_pin, 1);
    gpioDelay(30); // Changed delay to 30 microseconds

    gpioSetMode(gpio_pin, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio_pin) == 1) {
        gpioDelay(1); // Wait 1 microsecond
        timeout++;
        if (timeout > 100) { // Timeout after 100 microseconds
            fprintf(stderr, "Error: DHT22 timeout waiting for start signal (low). GPIO: %d\n", gpio_pin);
            return data; // Return invalid data
        }
    }

    timeout = 0;
    while (gpioRead(gpio_pin) == 0) {
        gpioDelay(1); // Wait 1 microsecond
        timeout++;
        if (timeout > 100) { // Timeout after 100 microseconds
            fprintf(stderr, "Error: DHT22 timeout waiting for start signal (high). GPIO: %d\n", gpio_pin);
            return data; // Return invalid data
        }
    }

    timeout = 0;
    while (gpioRead(gpio_pin) == 1) {
        gpioDelay(1); // Wait 1 microsecond
        timeout++;
        if (timeout > 100) { // Timeout after 100 microseconds
            fprintf(stderr, "Error: DHT22 timeout waiting for end of start signal. GPIO: %d\n", gpio_pin);
            return data; // Return invalid data
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio_pin) == 0) {
            gpioDelay(1); // Wait 1 microsecond
            timeout++;
            if (timeout > 100) { // Timeout after 100 microseconds
                fprintf(stderr, "Error: DHT22 timeout waiting for data bit start. GPIO: %d, Bit: %d\n", gpio_pin, i);
                return data; // Return invalid data
            }
        }

        pulse_count = 0;
        while (gpioRead(gpio_pin) == 1) {
            if (pulse_count < 80) {
                pulse_lengths[pulse_count++] = 0; // Record pulse length
            }
            gpioDelay(1); // Wait 1 microsecond
        }

        if (pulse_count > 0) {
            pulse_lengths[pulse_count - 1] = 1; // Mark the end of the pulse
        }

        int bit_value = 0;
        if (pulse_count > 3) {
            if (pulse_lengths[0] == 0 && pulse_lengths[1] == 1) {
                bit_value = 1;
            }
        }

        data_bits[i] = bit_value;
    }

    // Convert data bits to temperature and humidity
    int humidity_int = 0;
    int temperature_int = 0;
    int checksum = 0;

    for (i = 0; i < 16; i++) {
        humidity_int <<= 1;
        humidity_int |= data_bits[i];
    }

    for (i = 16; i < 32; i++) {
        temperature_int <<= 1;
        temperature_int |= data_bits[i];
    }

    for (i = 32; i < 40; i++) {
        checksum <<= 1;
        checksum |= data_bits[i];
    }

    // Validate checksum
    int calculated_checksum = (humidity_int & 0xFF) + (humidity_int >> 8) + (temperature_int & 0xFF) + (temperature_int >> 8);
    calculated_checksum &= 0xFF;

    if (checksum != calculated_checksum) {
        fprintf(stderr, "Error: DHT22 checksum error. GPIO: %d, Calculated: %d, Received: %d\n", gpio_pin, calculated_checksum, checksum);
        return data; // Return invalid data
    }

    // Convert data to temperature and humidity
    data.humidity = (float)humidity_int / 10.0;
    data.temperature = (float)temperature_int / 10.0;
    data.valid = 1;

    return data;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read DHT22 sensor 1
        DHT22Data sensor1_data = read_dht22(DHT22_GPIO_1);
        if (sensor1_data.valid) {
            printf("%s - Sensor 1 (GPIO %d): Temperature = %.1f°C, Humidity = %.1f%%\n", timestamp, DHT22_GPIO_1, sensor1_data.temperature, sensor1_data.humidity);
        } else {
            fprintf(stderr, "%s - Error reading sensor 1 (GPIO %d)\n", timestamp, DHT22_GPIO_1);
        }

        // Read DHT22 sensor 2
        DHT22Data sensor2_data = read_dht22(DHT22_GPIO_2);
        if (sensor2_data.valid) {
            printf("%s - Sensor 2 (GPIO %d): Temperature = %.1f°C, Humidity = %.1f%%\n", timestamp, DHT22_GPIO_2, sensor2_data.temperature, sensor2_data.humidity);
        } else {
            fprintf(stderr, "%s - Error reading sensor 2 (GPIO %d)\n", timestamp, DHT22_GPIO_2);
        }

        sleep(60); // Wait 60 seconds
    }

    gpioTerminate();
    return 0;
}

