#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t stop = 0;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    stop = 1;
}

int main()
{
    int ret;
    int value;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!stop) {
        // Toggle the GPIO line
        value = !gpiod_line_get_value(line);
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        // Print the current state
        printf("GPIO %d is %s\n", GPIO_PIN, value ? "HIGH" : "LOW");

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return 0;
}

