#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_16 16
#define GPIO_LINE_20 20

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_16 = NULL;
static struct gpiod_line *line_20 = NULL;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nCaught signal, exiting...\n");
}

int main()
{
    int ret;
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        fprintf(stderr, "Error: GPIO chip '%s' not found.  Try running as root?\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line handles
    line_16 = gpiod_chip_get_line(chip, GPIO_LINE_16);
    if (!line_16) {
        perror("gpiod_chip_get_line (GPIO 16)");
        gpiod_chip_close(chip);
        return 1;
    }

    line_20 = gpiod_chip_get_line(chip, GPIO_LINE_20);
    if (!line_20) {
        perror("gpiod_chip_get_line (GPIO 20)");
        gpiod_chip_close(chip);
        gpiod_line_release(line_16);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_16, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 16)");
        gpiod_chip_close(chip);
        gpiod_line_release(line_16);
        gpiod_line_release(line_20);
        return 1;
    }

    ret = gpiod_line_request_output(line_20, "gpio-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 20)");
        gpiod_chip_close(chip);
        gpiod_line_release(line_16);
        gpiod_line_release(line_20);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Toggle GPIO 16
        int value = gpiod_line_get_value(line_16);
        ret = gpiod_line_set_value(line_16, !value);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 16)");
            break;
        }
        printf("GPIO 16: %d\n", !value);

        // Toggle GPIO 20
        value = gpiod_line_get_value(line_20);
        ret = gpiod_line_set_value(line_20, !value);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 20)");
            break;
        }
        printf("GPIO 20: %d\n", !value);

        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line_16);
    gpiod_line_release(line_20);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to initialize the SPI interface
int spi_init(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_8 = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_8) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_32 = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_32) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the MAX31855
int read_max31855(int fd, uint8_t *data) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)NULL, // Read only
        .rx_buf = (unsigned long)data,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to parse the raw data and extract temperature and fault status
int parse_max31855_data(const uint8_t *data, float *temperature, uint8_t *fault) {
    // Check for fault bit
    if (data[3] & 0x01) {
        *fault = data[3] >> 1; // Extract fault code
        return -1; // Indicate fault
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0; // Indicate no fault
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    uint8_t data[4];
    float temperature;
    uint8_t fault;

    // Read data from MAX31855
    if (read_max31855(spi_fd, data) == 0) {
        // Parse the data
        if (parse_max31855_data(data, &temperature, &fault) == 0) {
            // Print the temperature
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            // Print fault status
            fprintf(stderr, "Fault detected: 0x%02X\n", fault);
            if (fault & 0x01) {
                fprintf(stderr, "  Open circuit fault\n");
            }
            if (fault & 0x02) {
                fprintf(stderr, "  Short to GND fault\n");
            }
            if (fault & 0x04) {
                fprintf(stderr, "  Short to VCC fault\n");
            }
        }
    } else {
        fprintf(stderr, "Failed to read data from MAX31855. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

