#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <string.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x03

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables for calibration data
static uint16_t dig_T1;
static int16_t dig_T2;
static int16_t dig_T3;
static uint16_t dig_P1;
static int16_t dig_P2;
static int16_t dig_P3;
static int16_t dig_P4;
static int16_t dig_P5;
static int16_t dig_P6;
static int16_t dig_P7;
static int16_t dig_P8;
static int16_t dig_P9;

// I2C file descriptor
static int i2c_fd = -1;

// Function to read a single byte from an I2C register
static int i2c_read_reg(int fd, uint8_t reg_addr, uint8_t *data)
{
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
static int i2c_write_reg(int fd, uint8_t reg_addr, uint8_t data)
{
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from I2C registers
static int i2c_read_block(int fd, uint8_t reg_addr, uint8_t *data, int len)
{
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read block data");
        return -1;
    }
    return 0;
}

// Function to initialize the BMP280 sensor
static int bmp280_init(int fd)
{
    uint8_t id;

    // Check the device ID
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) != 0) {
        fprintf(stderr, "Error reading BMP280 ID\n");
        return -1;
    }

    if (id != 0x58) {
        fprintf(stderr, "Incorrect BMP280 ID: 0x%02X\n", id);
        return -1;
    }

    // Read calibration data
    uint8_t calib_data[26];
    if (i2c_read_block(fd, BMP280_REG_CALIB_00, calib_data, 26) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    dig_T1 = (uint16_t)calib_data[0] | ((uint16_t)calib_data[1] << 8);
    dig_T2 = (int16_t)calib_data[2] | ((int16_t)calib_data[3] << 8);
    dig_T3 = (int16_t)calib_data[4] | ((int16_t)calib_data[5] << 8);
    dig_P1 = (uint16_t)calib_data[6] | ((uint16_t)calib_data[7] << 8);
    dig_P2 = (int16_t)calib_data[8] | ((int16_t)calib_data[9] << 8);
    dig_P3 = (int16_t)calib_data[10] | ((int16_t)calib_data[11] << 8);
    dig_P4 = (int16_t)calib_data[12] | ((int16_t)calib_data[13] << 8);
    dig_P5 = (int16_t)calib_data[14] | ((int16_t)calib_data[15] << 8);
    dig_P6 = (int16_t)calib_data[16] | ((int16_t)calib_data[17] << 8);
    dig_P7 = (int16_t)calib_data[18] | ((int16_t)calib_data[19] << 8);
    dig_P8 = (int16_t)calib_data[20] | ((int16_t)calib_data[21] << 8);
    dig_P9 = (int16_t)calib_data[22] | ((int16_t)calib_data[23] << 8);

    // Set the sensor to forced mode and configure other settings
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Error writing control register\n");
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) != 0) { // Filter off, standby time 0.5ms
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }

    return 0;
}

// Function to read temperature and pressure data from the BMP280
static int bmp280_read_data(int fd, float *temperature, float *pressure)
{
    uint8_t data[6];
    int32_t raw_temp, raw_press;
    int32_t var1, var2, T;
    double p;

    // Read the MSB, LSB and XLSB of the temperature and pressure registers
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading data registers\n");
        return -1;
    }

    raw_press = ((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | ((uint32_t)data[2] >> 4);
    raw_temp = ((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | ((uint32_t)data[5] >> 4);

    // Temperature compensation
    var1 = ((((raw_temp >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)dig_T1)) * ((raw_temp >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    T = var1 + var2;
    *temperature = (float)((T * 5 + 128) >> 8) / 100.0f;

    // Pressure compensation
    var1 = ((int32_t)T) - 128000;
    var2 = var1 * var1 * (int32_t)dig_P6;
    var2 = var2 + ((var1 * (int32_t)dig_P5) << 17);
    var2 = var2 + (((int32_t)dig_P4) << 35);
    var1 = ((var1 * var1 * (int32_t)dig_P3) >> 8) + ((var1 * (int32_t)dig_P2) << 12);
    var1 = (((((int32_t)1) << 47) + var1)) * ((int32_t)dig_P1) >> 33;

    if (var1 == 0)
    {
        return 0; // avoid exception caused by division by zero
    }
    p = 1048576.0 - raw_press;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int32_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int32_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int32_t)dig_P7) << 4);
    *pressure = (float)p / 100.0f;

    return 0;
}

int main()
{
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int retries = 3; // Number of retries for I2C initialization
    int i;

    // Open the I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address for the BMP280
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize the BMP280 sensor with retries
    for (i = 0; i < retries; i++) {
        if (bmp280_init(i2c_fd) == 0) {
            break; // Initialization successful
        } else {
            fprintf(stderr, "BMP280 initialization failed, retrying (%d/%d)\n", i + 1, retries);
            sleep(1); // Wait before retrying
        }
    }

    if (i == retries) {
        fprintf(stderr, "Failed to initialize BMP280 after %d retries\n", retries);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read and print temperature and pressure data
    float temperature, pressure;
    for (i = 0; i < 3; i++) {
        if (bmp280_read_data(i2c_fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read data from BMP280\n");
        }
        sleep(1); // Wait for 1 second
    }

    // Close the I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_22 22
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line17, *line22, *line23, *line24;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (line23) {
        gpiod_line_release(line23);
    }
    if (line24) {
        gpiod_line_release(line24);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for each pin
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    line22 = gpiod_chip_get_line(chip, GPIO_PIN_22);
    line23 = gpiod_chip_get_line(chip, GPIO_PIN_23);
    line24 = gpiod_chip_get_line(chip, GPIO_PIN_24);

    if (!line17 || !line22 || !line23 || !line24) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line17, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line22, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line 22 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line23, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line 23 for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line24, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line 24 for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial output values
    if (gpiod_line_set_value(line17, 0) < 0) {
        perror("Error setting GPIO line 17 value");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line22, 0) < 0) {
        perror("Error setting GPIO line 22 value");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line23, 0) < 0) {
        perror("Error setting GPIO line 23 value");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line24, 0) < 0) {
        perror("Error setting GPIO line 24 value");
        gpiod_chip_close(chip);
        return 1;
    }

    // Report initial state
    printf("GPIO 17: 0\n");
    printf("GPIO 22: 0\n");
    printf("GPIO 23: 0\n");
    printf("GPIO 24: 0\n");

    // Wait for 5 seconds
    sleep(5);

    // Set output values to 1
    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("Error setting GPIO line 17 value");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line22, 1) < 0) {
        perror("Error setting GPIO line 22 value");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line23, 1) < 0) {
        perror("Error setting GPIO line 23 value");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_set_value(line24, 1) < 0) {
        perror("Error setting GPIO line 24 value");
        gpiod_chip_close(chip);
        return 1;
    }

    // Report new state
    printf("GPIO 17: 1\n");
    printf("GPIO 22: 1\n");
    printf("GPIO 23: 1\n");
    printf("GPIO 24: 1\n");

    // Wait for 5 seconds
    sleep(5);

    // Release GPIO lines
    gpiod_line_release(line17);
    gpiod_line_release(line22);
    gpiod_line_release(line23);
    gpiod_line_release(line24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define GPIO_NAME "my-gpio"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

int main()
{
    int ret;
    int value;

    // Register signal handlers for graceful shutdown
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, GPIO_NAME, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Read value from stdin
    if (scanf("%d", &value) != 1) {
        fprintf(stderr, "Invalid input. Expected an integer.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Validate input
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid input. Expected 0 or 1.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO output
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Print output state
    printf("GPIO %d set to %d\n", GPIO_PIN, value);

    // Release GPIO line and close chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define the GPIO chip and line number
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

// Define the GPIO line name
#define GPIO_NAME "my_gpio_line"

// Define the GPIO line direction
#define GPIO_DIRECTION GPIOD_LINE_REQUEST_DIRECTION_OUTPUT

// Define the GPIO line value
#define GPIO_VALUE 1

// Define the sleep duration in seconds
#define SLEEP_DURATION 1

// Global variables for GPIO chip and line
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release the GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    struct timespec sleep_time;

    // Set up the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, GPIO_NAME, GPIO_DIRECTION, GPIO_VALUE);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_LINE, strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line value
    ret = gpiod_line_set_value(line, GPIO_VALUE);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value to %d: %s\n", GPIO_LINE, GPIO_VALUE, strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print the GPIO line value
    printf("GPIO line %d value set to %d\n", GPIO_LINE, GPIO_VALUE);

    // Sleep for the specified duration
    sleep_time.tv_sec = SLEEP_DURATION;
    sleep_time.tv_nsec = 0;
    nanosleep(&sleep_time, NULL);

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data);
int bme280_init(int fd);
int bme280_read_data(int fd, float *temperature, float *pressure, float *humidity);
void signal_handler(int signal);
int read_calibration_data(int fd, struct bme280_calib_data *calib);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// BME280 initialization function
int bme280_init(int fd) {
    // Check the device ID
    uint8_t id;
    if (i2c_read_bytes(fd, BME280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Error reading BME280 ID.\n");
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Incorrect BME280 ID: 0x%02X\n", id);
        return -1;
    }

    // Read calibration data
    if (read_calibration_data(fd, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data.\n");
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2c_write_byte(fd, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error writing to CTRL_HUM register.\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    if (i2c_write_byte(fd, BME280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register.\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data(int fd, struct bme280_calib_data *calib) {
    uint8_t data[26];
    if (i2c_read_bytes(fd, BME280_REG_CALIB_00, data, 26) != 0) {
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib->dig_H1 = data[25];

    uint8_t data_h[7];
    if (i2c_read_bytes(fd, BME280_REG_CALIB_26, data_h, 7) != 0) {
        return -1;
    }

    calib->dig_H2 = (int16_t)data_h[0] | ((int16_t)data_h[1] << 8);
    calib->dig_H3 = data_h[2];
    calib->dig_H4 = (int16_t)((data_h[3] << 4) | (data_h[4] & 0x0F));
    calib->dig_H5 = (int16_t)((data_h[5] << 4) | (data_h[4] >> 4));
    calib->dig_H6 = (int8_t)data_h[6];

    return 0;
}

// BME280 data reading function
int bme280_read_data(int fd, float *temperature, float *pressure, float *humidity) {
    uint8_t data[8];
    int32_t raw_temp, raw_press, raw_hum;

    // Read temperature, pressure, and humidity data
    if (i2c_read_bytes(fd, BME280_REG_PRESS_MSB, data, 8) != 0) {
        fprintf(stderr, "Error reading data registers.\n");
        return -1;
    }

    raw_press = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    raw_temp = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;
    raw_hum = (int32_t)data[6] << 8 | (int32_t)data[7];

    // Temperature compensation
    double var1 = (raw_temp / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temp / 131072.0 - calib.dig_T1 / 8192.0) *
                   (raw_temp / 131072.0 - calib.dig_T1 / 8192.0)) *
                  calib.dig_T3;
    double t_fine = var1 + var2;
    *temperature = (t_fine / 5120.0);

    // Pressure compensation
    double var3 = t_fine / 2.0 - 64000.0;
    double var4 = var3 * var3 * calib.dig_P6 / 32768.0;
    double var5 = var4 + var3 * calib.dig_P5 * 2.0;
    double var6 = var5 / 4.0 + calib.dig_P4 * 65536.0;
    double var7 = calib.dig_P3 * var3 * var3 / 524288.0;
    double var8 = calib.dig_P2 * var3 / 524288.0;
    double var9 = 1.0 + (var7 + var8 + var6) / 32768.0;
    double pressure_val = 1048576.0 - raw_press;
    pressure_val = (pressure_val - var6 / 4096.0) * 6250.0 / var9;
    var3 = calib.dig_P9 * pressure_val * pressure_val / 2147483648.0;
    var4 = pressure_val * calib.dig_P8 / 32768.0;
    *pressure = pressure_val + (var3 + var4 + calib.dig_P7) / 16.0;

    // Humidity compensation
    double var_H = t_fine - 76800.0;
    double humidity_val = (raw_hum - (calib.dig_H4 * 64.0 + calib.dig_H5 / 16384.0 * var_H)) *
                          (calib.dig_H2 / 65536.0 * (1.0 + calib.dig_H6 / 67108864.0 * var_H *
                                                     (1.0 + calib.dig_H3 / 67108864.0 * var_H)));
    *humidity = humidity_val * (1.0 - calib.dig_H1 * humidity_val / 524288.0);
    if (*humidity > 100.0)
        *humidity = 100.0;
    else if (*humidity < 0.0)
        *humidity = 0.0;

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize BME280 sensor
    if (bme280_init(i2c_fd) != 0) {
        fprintf(stderr, "BME280 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    float temperature, pressure, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Main loop
    for (int i = 0; i < 3 && program_running; i++) {
        // Read sensor data
        if (bme280_read_data(i2c_fd, &temperature, &pressure, &humidity) == 0) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Print data to standard output
            printf("%s - Temperature: %.2f °C, Pressure: %.2f hPa, Humidity: %.2f %%\n",
                   timestamp, temperature, pressure, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

