#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the VEML7700 sensor
int init_veml7700(int fd) {
    // Configuration value: Integration time = 100ms, Gain = 2
    uint16_t config_value = 0x0000; // Default configuration
    config_value |= (0x00 << 11); // Integration time: 100ms
    config_value |= (0x02 << 6);  // Gain: 2
    config_value |= (0x00 << 1);  // ALS_SD: 0
    config_value |= (0x00 << 0);  // ALS_EN: 0

    uint8_t config_data[2];
    config_data[0] = (config_value >> 8) & 0xFF;
    config_data[1] = config_value & 0xFF;

    if (write(fd, config_data, 2) != 2) {
        perror("Failed to write configuration to VEML7700");
        return -1;
    }

    return 0;
}

// Function to read ALS data from the VEML7700 sensor
int read_als_data(int fd, uint16_t *als_data) {
    uint8_t data[2];

    // Set register pointer to ALS_DATA
    if (write(fd, (uint8_t[]){VEML7700_ALS_DATA}, 1) != 1) {
        perror("Failed to set register pointer");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read ALS data");
        return -1;
    }

    *als_data = (data[1] << 8) | data[0];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the VEML7700 sensor
    if (init_veml7700(i2c_fd) != 0) {
        fprintf(stderr, "VEML7700 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t als_data;

        if (read_als_data(i2c_fd, &als_data) == 0) {
            printf("ALS Data: %u\n", als_data);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }

        sleep(0.5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Define the UART port (e.g., /dev/ttyS0 or /dev/ttyAMA0)
#define UART_PORT "/dev/ttyS0"

// Define the baud rate
#define BAUD_RATE B115200

// Define the timeout in seconds
#define TIMEOUT 5

// Global variable for the UART file descriptor
int uart_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (uart_fd != -1) {
        close(uart_fd);
    }
    exit(0);
}

// Function to initialize the UART port
int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // Set baud rate, 8 data bits, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read at least 0 characters
    tty.c_cc[VTIME] = 1;                             // Wait for 0.1 seconds (1 decisecond)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    }
}

// Function to process the received data (print to stdout)
void process_data(const char *data) {
    printf("%s", data);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the UART port
    uart_fd = init_uart(UART_PORT);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to initialize UART. Exiting.\n");
        return 1;
    }

    char buffer[256]; // Buffer to store received data

    // Main loop to read and process data
    while (1) {
        int bytes_read = read_uart(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            process_data(buffer);
        } else if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            // Attempt to re-initialize the UART
            close(uart_fd);
            uart_fd = init_uart(UART_PORT);
            if (uart_fd == -1) {
                fprintf(stderr, "Failed to re-initialize UART. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
        }

        // Wait for 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Close the UART port before exiting
    close(uart_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout for echo pulse in microseconds

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to trigger the HC-SR04
void trigger_hc_sr04()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance in centimeters
float measure_distance()
{
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    trigger_hc_sr04();

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Echo pulse start timeout.\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        gpioDelay(1); // Wait 1 us
        count++;
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Echo pulse end timeout.\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate the pulse duration
    diff_tick = end_tick - start_tick;

    // Calculate the distance
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = measure_distance();

        if (distance > 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else
        {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        gpioDelay(500); // Wait 0.5 seconds
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

