#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        // Reset ADXL345 to standby mode
        uint8_t reset_data = 0x00;
        if (write(i2c_fd, &reset_data, 1) != 1) {
            perror("Failed to reset ADXL345");
        }
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the ADXL345
bool adxl345_init(int fd) {
    // Set POWER_CTL register to start measurement
    uint8_t power_ctl_data = 0x08; // Measurement mode
    if (write(fd, &power_ctl_data, 1) != 1) {
        perror("Failed to write to POWER_CTL register");
        return false;
    }
    return true;
}

// Function to read acceleration data from ADXL345
bool adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    // Read 6 bytes of data (X, Y, Z axis)
    if (read(fd, data, 6) != 6) {
        perror("Failed to read acceleration data");
        return false;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return true;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (!adxl345_init(i2c_fd)) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read acceleration data
        if (adxl345_read_acceleration(i2c_fd, &x, &y, &z)) {
            // Print acceleration values
            printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    return 0;
}

