#define PWM_PIN 18 // BCM GPIO 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    int i;
    int duty_cycle;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as an output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Main loop
    while (!terminate) {
        // Generate PWM signal with duty cycle ranging from 0 to 255
        for (duty_cycle = 0; duty_cycle <= 255; duty_cycle++) {
            gpioPWM(PWM_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            fflush(stdout); // Ensure output is displayed immediately
            gpioDelay(10000); // 10 ms delay (10000 microseconds)
        }

        // Delay before starting the next cycle
        gpioDelay(100000); // 100 ms delay (100000 microseconds)
