    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line for each pin
    int gpio_pins[NUM_GPIO_PINS] = {GPIO_PIN_0, GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3, GPIO_PIN_4, GPIO_PIN_5, GPIO_PIN_12, GPIO_PIN_17};
    for (int i = 0; i < NUM_GPIO_PINS; i++)
    {
        gpio_lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!gpio_lines[i])
        {
            perror("Error getting GPIO line");
            // Release previously acquired lines before exiting
            for (int j = 0; j < i; j++) {
                if (gpio_lines[j] != NULL) {
                    gpiod_line_release(gpio_lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Request the GPIO lines for output
    for (int i = 0; i < NUM_GPIO_PINS; i++)
    {
        if (gpiod_line_request_output(gpio_lines[i], "gpio-control", 0) < 0)
        {
            perror("Error requesting GPIO line for output");
            // Release previously acquired lines before exiting
            for (int j = 0; j < i; j++) {
                if (gpio_lines[j] != NULL) {
                    gpiod_line_release(gpio_lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    for (int i = 0; i < NUM_ITERATIONS; i++)
    {
        // Toggle the GPIO pins
        for (int j = 0; j < NUM_GPIO_PINS; j++)
        {
            int value = !gpiod_line_get_value(gpio_lines[j]);
            if (gpiod_line_set_value(gpio_lines[j], value) < 0)
            {
                perror("Error setting GPIO line value");
                // Release previously acquired lines before exiting
                for (int k = 0; k < NUM_GPIO_PINS; k++) {
                    if (gpio_lines[k] != NULL) {
                        gpiod_line_release(gpio_lines[k]);
                    }
                }
                gpiod_chip_close(chip);
