#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout in microseconds

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int echo_received = 0;
static volatile int timeout_occured = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void timeout_callback();
double calculate_distance(int pulse_width);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1;
    } else if (level == 0 && echo_received) {
        pulse_end = tick;
        echo_received = 0;
    }
}

// Callback function for timeout
void timeout_callback() {
    timeout_occured = 1;
}

// Function to trigger the ultrasonic pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance from pulse width
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback functions
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up timeout callback
    gpioSetTimerFuncEx(0, TIMEOUT_US / 1000, timeout_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        timeout_occured = 0; // Reset timeout flag
        pulse_start = 0;      // Reset pulse start time
        pulse_end = 0;        // Reset pulse end time
        echo_received = 0;    // Reset echo received flag

        trigger_pulse(); // Send the trigger pulse

        // Wait for echo or timeout
        while (!pulse_end && !timeout_occured) {
            gpioDelay(100); // Small delay to avoid busy-waiting
        }

        if (timeout_occured) {
            fprintf(stderr, "Timeout occurred!\n");
            continue; // Skip to the next iteration
        }

        // Calculate pulse width
        int pulse_width = pulse_end - pulse_start;

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        gpioDelay(500); // Delay between measurements
    }

    // Cleanup (this part will not be reached in the infinite loop)
    gpioTerminate();
    return 0;
}

