#define PWM_PIN 16  // BCM GPIO 16

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    int i;
    int duty_cycle;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 16 as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Set PWM range to 1000 (0-1000)
    gpioSetPWMrange(PWM_PIN, 1000);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    for (i = 0; i <= 1000 && !terminate; i += 50) {
        duty_cycle = i;
        gpioPWM(PWM_PIN, duty_cycle);
        printf("Duty Cycle: %d\n", duty_cycle);
        gpioDelay(100000); // 100ms delay
    }

    // Clean up and terminate pigpio
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the TCS34725 sensor
int init_tcs34725(int fd) {
    // Enable the sensor (power on and enable RGBC)
    uint8_t enable_value = 0x03; // PON (Power ON) and AEN (RGBC Enable)
    if (write(fd, &enable_value, 1) != 1) {
        perror("Failed to write to TCS34725_ENABLE");
        return -1;
    }

    // Set integration time (ATIME) - e.g., 101ms
    uint8_t atime_value = 0xDB; // 101ms
    if (write(fd, &atime_value, 1) != 1) {
        perror("Failed to write to TCS34725_ATIME");
        return -1;
    }

    // Set gain (AGAIN) - e.g., 60x
    uint8_t control_value = 0x01; // Gain = 60x
    if (write(fd, &control_value, 1) != 1) {
        perror("Failed to write to TCS34725_CONTROL");
        return -1;
    }

    return 0;
}

// Function to read a register from the TCS34725 sensor
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the TCS34725 sensor
int read_16bit_value(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read 16-bit value");
        return -1;
    }

    *value = (buffer[1] << 8) | buffer[0];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (init_tcs34725(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize TCS34725 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (1) {
        uint16_t clear, red, green, blue;

        // Read color data
        if (read_16bit_value(i2c_fd, TCS34725_CDATA, &clear) != 0) {
            fprintf(stderr, "Failed to read clear data.\n");
            continue; // Continue to the next iteration
        }
        if (read_16bit_value(i2c_fd, TCS34725_RDATA, &red) != 0) {
            fprintf(stderr, "Failed to read red data.\n");
            continue; // Continue to the next iteration
        }
        if (read_16bit_value(i2c_fd, TCS34725_GDATA, &green) != 0) {
            fprintf(stderr, "Failed to read green data.\n");
            continue; // Continue to the next iteration
        }
        if (read_16bit_value(i2c_fd, TCS34725_BDATA, &blue) != 0) {
            fprintf(stderr, "Failed to read blue data.\n");
            continue; // Continue to the next iteration
        }

        // Print the color data
        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

