#include <pigpio.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_17, PI_OUTPUT);

    // Set GPIO 18 as an output
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Toggle GPIO 17
        gpioWrite(GPIO_17, !gpioRead(GPIO_17));

        // Toggle GPIO 18
        gpioWrite(GPIO_18, !gpioRead(GPIO_18));

        // Print the current state of GPIO 17 and GPIO 18
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_17, gpioRead(GPIO_17), GPIO_18, gpioRead(GPIO_18));

        // Wait for 0.01 seconds
        gpioDelay(10000); // 10000 microseconds = 0.01 seconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

