#define PWM_PIN_2 3
#define PWM_PIN_3 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 192); // 60% duty cycle
        gpioPWM(PWM_PIN_3, 64);  // 30% duty cycle

        // Report the PWM states to standard output
        printf("PWM1: %d, PWM2: %d, PWM3: %d\n", gpioGetPWMdutycycle(PWM_PIN_1), gpioGetPWMdutycycle(PWM_PIN_2), gpioGetPWMdutycycle(PWM_PIN_3));

        // Wait for 5 seconds
        sleep(5);
    }

    // Stop PWM on all pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate the pigpio library
    gpioTerminate();

    // Exit successfully
    return 0;
}

