// Define the UART port (e.g., /dev/ttyS0 or /dev/ttyAMA0)
#define UART_PORT "/dev/ttyS0"

// Define the baud rate
#define BAUD_RATE B115200

// Define the timeout in seconds
#define TIMEOUT 5

// Global variable for the UART file descriptor
int uart_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (uart_fd != -1) {
        close(uart_fd);
    }
    exit(0);
}

// Function to initialize the UART port
int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // Set baud rate, 8 data bits, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read at least 0 characters
    tty.c_cc[VTIME] = 10;                            // Wait for 1 second (10 deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart(int fd, char *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    }
}

// Function to parse the received data
int parse_data(const char *data) {
    // Implement your data parsing logic here
    // This is a placeholder; replace with actual parsing logic
    printf("Received data: %s\n", data);
    return 0; // Indicate success
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the UART port
    uart_fd = init_uart(UART_PORT);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to initialize UART. Exiting.\n");
        return 1;
    }

    printf("UART initialized on %s. Reading data...\n", UART_PORT);

    // Main loop
    char buffer[256];
    time_t start_time = time(NULL);
    while (1) {
        int bytes_read = read_uart(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            if (parse_data(buffer) != 0) {
                fprintf(stderr, "Error parsing data.\n");
            }
            start_time = time(NULL); // Reset timeout
        } else if (bytes_read < 0) {
            // Error reading, but not necessarily a timeout
            fprintf(stderr, "Error reading from UART, but continuing...\n");
        }

        // Check for timeout
        if (time(NULL) - start_time > TIMEOUT) {
            fprintf(stderr, "Timeout waiting for data. Exiting.\n");
            break;
        }

        usleep(100000); // Sleep for 0.1 seconds (100000 microseconds)
    }

    // Clean up and exit
    close(uart_fd);
    printf("Program finished.\n");
    return 0;
}

