#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Define timeout duration (in microseconds)
#define TIMEOUT 500000 // 0.5 seconds

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the HC-SR04
void trigger_hc_sr04()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance in centimeters
float measure_distance()
{
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    trigger_hc_sr04();

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT)
    {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT)
    {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT)
    {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT)
    {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate the pulse duration in microseconds
    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters (speed of sound: 343 m/s)
    // distance = (pulse_duration * 0.000001) * 34300 / 2
    float distance = (float)diff_tick * 0.000001 * 34300 / 2.0;

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = measure_distance();

        if (distance >= 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else
        {
            fprintf(stderr, "Error: Could not measure distance.\n");
        }

        gpioDelay(100); // Delay between measurements (100 milliseconds)
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

